screenPanels.initJs:
function(container, apiUrl, tables) {
  const salesTable = tables[0]; // 売上実績データ
  const storeTable = tables[1]; // 店舗マスタ
  const productTable = tables[2]; // 商品マスタ

  let allSalesData = [];
  let allStores = [];
  let allProducts = [];

  // 曜日変換
  const getDayOfWeek = (dateStr) => {
    const days = ['日', '月', '火', '水', '木', '金', '土'];
    const date = new Date(dateStr);
    return days[date.getDay()];
  };

  // 金額フォーマット
  const formatAmount = (amount) => {
    return new Intl.NumberFormat('ja-JP').format(amount);
  };

  // 店舗名取得
  const getStoreName = (storeId) => {
    const store = allStores.find(s => s.id === storeId);
    return store ? store.店舗名 : '不明';
  };

  // 商品名取得
  const getProductName = (productId) => {
    const product = allProducts.find(p => p.id === productId);
    return product ? product.商品名 : '不明';
  };

  // テーブル再描画
  function renderRows(rows) {
    const tbody = container.querySelector('#sales-tbody');
    tbody.innerHTML = rows.map(row => `
      <tr data-id="${row.id}">
        <td>${row.売上日 ? new Date(row.売上日).toLocaleDateString('ja-JP') : ''}</td>
        <td>${getStoreName(row.店舗ID)}</td>
        <td>${getProductName(row.商品ID)}</td>
        <td>${formatAmount(row.販売数量 || 0)}</td>
        <td>¥${formatAmount(row.単価 || 0)}</td>
        <td>¥${formatAmount(row.売上金額 || 0)}</td>
        <td>${getDayOfWeek(row.売上日)}</td>
        <td>${row.特売フラグ ? '特売' : '通常'}</td>
        <td>
          <button class="action-btn secondary edit-btn" data-id="${row.id}">編集</button>
          <button class="action-btn secondary delete-btn" data-id="${row.id}">削除</button>
        </td>
      </tr>
    `).join('');
  }

  // ドロップダウン初期化
  function initDropdowns() {
    const filterStore = container.querySelector('#filter-store');
    const filterProduct = container.querySelector('#filter-product');
    const formStore = container.querySelector('#form-store');
    const formProduct = container.querySelector('#form-product');

    // 店舗選択肢
    allStores.forEach(store => {
      if (store.有効フラグ) {
        const option1 = new Option(store.店舗名, store.id);
        const option2 = new Option(store.店舗名, store.id);
        filterStore.appendChild(option1);
        formStore.appendChild(option2);
      }
    });

    // 商品選択肢
    allProducts.forEach(product => {
      if (product.有効フラグ) {
        const option1 = new Option(product.商品名, product.id);
        const option2 = new Option(product.商品名, product.id);
        filterProduct.appendChild(option1);
        formProduct.appendChild(option2);
      }
    });
  }

  // 初期データ読み込み
  async function loadInitialData() {
    try {
      const [salesData, storeData, productData] = await Promise.all([
        window.aivicApi.list(0),
        window.aivicApi.list(1),
        window.aivicApi.list(2)
      ]);

      allSalesData = salesData || salesTable.records || [];
      allStores = storeData || storeTable.records || [];
      allProducts = productData || productTable.records || [];

      initDropdowns();
      renderRows(allSalesData);
    } catch (error) {
      console.error('データ読み込みエラー:', error);
      allSalesData = salesTable.records || [];
      allStores = storeTable.records || [];
      allProducts = productTable.records || [];
      initDropdowns();
      renderRows(allSalesData);
    }
  }

  // 検索・絞り込み
  container.querySelector('#btn-search').addEventListener('click', async () => {
    const storeId = container.querySelector('#filter-store').value;
    const productId = container.querySelector('#filter-product').value;
    const startDate = container.querySelector('#filter-date-start').value;
    const endDate = container.querySelector('#filter-date-end').value;

    try {
      const rows = await window.aivicApi.list(0);
      let filtered = rows || [];

      if (storeId) {
        filtered = filtered.filter(r => r.店舗ID === storeId);
      }
      if (productId) {
        filtered = filtered.filter(r => r.商品ID === productId);
      }
      if (startDate) {
        filtered = filtered.filter(r => r.売上日 >= startDate);
      }
      if (endDate) {
        filtered = filtered.filter(r => r.売上日 <= endDate);
      }

      renderRows(filtered);
    } catch (error) {
      console.error('検索エラー:', error);
    }
  });

  // 新規登録ボタン
  container.querySelector('#btn-new').addEventListener('click', () => {
    container.querySelector('#modal-title').textContent = '売上実績登録';
    container.querySelector('#edit-id').value = '';
    container.querySelector('#sales-form').reset();
    container.querySelector('#sales-modal').classList.remove('hidden');
  });

  // モーダル閉じる
  container.querySelector('#modal-close').addEventListener('click', () => {
    container.querySelector('#sales-modal').classList.remove('hidden');
  });

  container.querySelector('#btn-cancel').addEventListener('click', () => {
    container.querySelector('#sales-modal').classList.add('hidden');
  });

  // 売上金額自動計算
  const updateAmount = () => {
    const quantity = parseFloat(container.querySelector('#form-quantity').value) || 0;
    const price = parseFloat(container.querySelector('#form-price').value) || 0;
    container.querySelector('#form-amount').value = quantity * price;
  };

  container.querySelector('#form-quantity').addEventListener('input', updateAmount);
  container.querySelector('#form-price').addEventListener('input', updateAmount);

  // フォーム保存
  container.querySelector('#sales-form').addEventListener('submit', async (e) => {
    e.preventDefault();

    const formData = {
      店舗ID: container.querySelector('#form-store').value,
      商品ID: container.querySelector('#form-product').value,
      売上日: container.querySelector('#form-date').value,
      販売数量: parseInt(container.querySelector('#form-quantity').value),
      単価: parseInt(container.querySelector('#form-price').value),
      売上金額: parseInt(container.querySelector('#form-amount').value),
      特売フラグ: container.querySelector('#form-sale').value === 'true',
      割引率: parseInt(container.querySelector('#form-discount').value) || 0,
      曜日区分: new Date(container.querySelector('#form-date').value).getDay() + 1,
      祝日フラグ: false,
      在庫切れフラグ: false,
      データ取込日時: new Date().toISOString(),
      作成日時: new Date().toISOString(),
      更新日時: new Date().toISOString(),
      作成者ID: 'current-user'
    };

    // バリデーション
    if (!formData.店舗ID) {
      alert('店舗を選択してください');
      return;
    }
    if (!formData.商品ID) {
      alert('商品を選択してください');
      return;
    }
    if (!formData.売上日) {
      alert('売上日を入力してください');
      return;
    }
    if (new Date(formData.売上日) > new Date()) {
      alert('未来の日付は入力できません');
      return;
    }
    if (formData.販売数量 < 0) {
      alert('売上数量は0以上の値を入力してください');
      return;
    }
    if (formData.単価 < 0) {
      alert('単価は0以上の値を入力してください');
      return;
    }

    try {
      const editId = container.querySelector('#edit-id').value;
      if (editId) {
        await window.aivicApi.update(0, editId, formData);
      } else {
        await window.aivicApi.save(0, formData);
      }

      container.querySelector('#sales-modal').classList.add('hidden');
      const updatedRows = await window.aivicApi.list(0);
      renderRows(updatedRows);
    } catch (error) {
      console.error('保存エラー:', error);
      alert('保存に失敗しました');
    }
  });

  // 行レベル操作（編集・削除）
  container.addEventListener('click', async (e) => {
    const editBtn = e.target.closest('.edit-btn');
    const deleteBtn = e.target.closest('.delete-btn');

    if (editBtn) {
      const id = editBtn.dataset.id;
      const row = allSalesData.find(r => r.id === id);
      if (!row) {
        alert('指定されたデータが見つかりません');
        return;
      }

      container.querySelector('#modal-title').textContent = '売上実績編集';
      container.querySelector('#edit-id').value = id;
      container.querySelector('#form-store').value = row.店舗ID || '';
      container.querySelector('#form-product').value = row.商品ID || '';
      container.querySelector('#form-date').value = row.売上日 ? row.売上日.split('T')[0] : '';
      container.querySelector('#form-quantity').value = row.販売数量 || '';
      container.querySelector('#form-price').value = row.単価 || '';
      container.querySelector('#form-amount').value = row.売上金額 || '';
      container.querySelector('#form-sale').value = row.特売フラグ ? 'true' : 'false';
      container.querySelector('#form-discount').value = row.割引率 || 0;
      container.querySelector('#sales-modal').classList.remove('hidden');
    }

    if (deleteBtn) {
      const id = deleteBtn.dataset.id;
      if (!confirm('この売上実績データを削除しますか？')) return;

      try {
        await window.aivicApi.delete(0, id);
        const updatedRows = await window.aivicApi.list(0);
        renderRows(updatedRows);
      } catch (error) {
        console.error('削除エラー:', error);
        alert('指定されたデータが存在しません');
      }
    }
  });

  // CSVエクスポート
  container.querySelector('#btn-export').addEventListener('click', async () => {
    try {
      const rows = await window.aivicApi.list(0);
      const headers = ['売上日', '店舗名', '商品名', '販売数量', '単価', '売上金額', '曜日', '特売フラグ'];
      const csvData = [
        headers.join(','),
        ...rows.map(row => [
          row.売上日 ? new Date(row.売上日).toLocaleDateString('ja-JP') : '',
          `"${getStoreName(row.店舗ID)}"`,
          `"${getProductName(row.商品ID)}"`,
          row.販売数量 || 0,
          row.単価 || 0,
          row.売上金額 || 0,
          getDayOfWeek(row.売上日),
          row.特売フラグ ? '特売' : '通常'
        ].join(','))
      ].join('\n');

      const blob = new Blob(['\uFEFF' + csvData], { type: 'text/csv;charset=utf-8;' });
      const link = document.createElement('a');
      link.href = URL.createObjectURL(blob);
      link.download = `売上実績_${new Date().toISOString().split('T')[0]}.csv`;
      link.click();
    } catch (error) {
      console.error('エクスポートエラー:', error);
    }
  });

  // インポートモーダル
  container.querySelector('#btn-import').addEventListener('click', () => {
    container.querySelector('#import-modal').classList.remove('hidden');
  });

  container.querySelector('#import-close').addEventListener('click', () => {
    container.querySelector('#import-modal').classList.add('hidden');
  });

  // テンプレートダウンロード
  container.querySelector('#btn-template').addEventListener('click', () => {
    const headers = ['店舗ID', '商品ID', '売上日', '販売数量', '単価', '売上金額', '特売フラグ', '割引率'];
    const csvData = headers.join(',');
    const blob = new Blob(['\uFEFF' + csvData], { type: 'text/csv;charset=utf-8;' });
    const link = document.createElement('a');
    link.href = URL.createObjectURL(blob);
    link.download = '売上実績テンプレート.csv';
    link.click();
  });

  // ドラッグ&ドロップ
  const dropZone = container.querySelector('#drop-zone');
  const fileInput = container.querySelector('#csv-file');

  dropZone.addEventListener('click', () => fileInput.click());
  dropZone.addEventListener('dragover', (e) => {
    e.preventDefault();
    dropZone.classList.add('dragover');
  });
  dropZone.addEventListener('dragleave', () => {
    dropZone.classList.remove('dragover');
  });
  dropZone.addEventListener('drop', (e) => {
    e.preventDefault();
    dropZone.classList.remove('dragover');
    const files = e.dataTransfer.files;
    if (files.length > 0) {
      handleFile(files[0]);
    }
  });

  fileInput.addEventListener('change', (e) => {
    if (e.target.files.length > 0) {
      handleFile(e.target.files[0]);
    }
  });

  function handleFile(file) {
    if (!file.name.endsWith('.csv')) {
      alert('CSVファイルを選択してください');
      return;
    }

    const reader = new FileReader();
    reader.onload = (e) => {
      const csv = e.target.result;
      const lines = csv.split('\n').filter(line => line.trim());
      if (lines.length < 2) {
        alert('データが含まれていません');
        return;
      }

      const headers = lines[0].split(',');
      const previewData = lines.slice(1, 11); // 最初の10行のみプレビュー

      // プレビューテーブル表示
      const previewThead = container.querySelector('#preview-thead');
      const previewTbody = container.querySelector('#preview-tbody');

      previewThead.innerHTML = `<tr>${headers.map(h => `<th>${h}</th>`).join('')}</tr>`;
      previewTbody.innerHTML = previewData.map(line => {
        const cells = line.split(',');
        return `<tr>${cells.map(cell => `<td>${cell}</td>`).join('')}</tr>`;
      }).join('');

      container.querySelector('#preview-section').classList.remove('hidden');
    };
    reader.readAsText(file);
  }

  // 一括インポート実行
  container.querySelector('#btn-bulk-import').addEventListener('click', async () => {
    const file = fileInput.files[0];
    if (!file) return;

    const reader = new FileReader();
    reader.onload = async (e) => {
      const csv = e.target.result;
      const lines = csv.split('\n').filter(line => line.trim());
      const dataLines = lines.slice(1);

      let imported = 0;
      let failed = 0;

      for (const line of dataLines) {
        const cells = line.split(',');
        if (cells.length < 6) continue;

        const rowData = {
          店舗ID: cells[0]?.trim(),
          商品ID: cells[1]?.trim(),
          売上日: cells[2]?.trim(),
          販売数量: parseInt(cells[3]) || 0,
          単価: parseInt(cells[4]) || 0,
          売上金額: parseInt(cells[5]) || 0,
          特売フラグ: cells[6]?.trim() === 'true',
          割引率: parseInt(cells[7]) || 0,
          曜日区分: new Date(cells[2]).getDay() + 1,
          祝日フラグ: false,
          在庫切れフラグ: false,
          データ取込日時: new Date().toISOString(),
          作成日時: new Date().toISOString(),
          更新日時: new Date().toISOString(),
          作成者ID: 'current-user'
        };

        try {
          await window.aivicApi.save(0, rowData);
          imported++;
        } catch (error) {
          failed++;
        }
      }

      alert(`インポート完了\n成功: ${imported}件\n失敗: ${failed}件`);
      container.querySelector('#import-modal').classList.add('hidden');
      const updatedRows = await window.aivicApi.list(0);
      renderRows(updatedRows);
    };
    reader.readAsText(file);
  });

  // 初期化実行
  loadInitialData();
}

function(container, apiUrl, tables) {
  // 予測結果データを保持
  let currentPredictionData = [];
  let allProductForecasts = [];

  // 店舗データを店舗選択に設定
  function loadStores() {
    const storeSelect = container.querySelector('#store-select');
    const storeTable = tables.find(t => t.tableName === '店舗マスタ');
    if (storeTable && storeTable.records) {
      storeTable.records.forEach(store => {
        if (store.有効フラグ) {
          const option = document.createElement('option');
          option.value = store.店舗ID;
          option.textContent = `${store.店舗コード} - ${store.店舗名}`;
          storeSelect.appendChild(option);
        }
      });
    }
  }

  // 商品別予測一覧の再描画
  function renderProductForecasts(forecasts) {
    const tbody = container.querySelector('#product-forecast-tbody');
    tbody.innerHTML = forecasts.map(forecast => `
      <tr data-id="${forecast.予測結果ID}">
        <td>${forecast.商品コード || '-'}</td>
        <td>${forecast.商品名 || '-'}</td>
        <td>${forecast.予測対象日 ? new Date(forecast.予測対象日).toLocaleDateString('ja-JP') : '-'}</td>
        <td>${forecast.予測数量 || 0}</td>
        <td>${forecast.推奨発注数量 || 0}</td>
        <td>${forecast.予測精度 || 0}%</td>
        <td>
          <span style="padding: 4px 8px; border-radius: 4px; font-size: 12px; background: ${
            forecast.予測ステータス === '完了' ? 'rgba(34, 197, 94, 0.1)' :
            forecast.予測ステータス === '算出中' ? 'rgba(59, 130, 246, 0.1)' :
            'rgba(239, 68, 68, 0.1)'
          }; color: ${
            forecast.予測ステータス === '完了' ? '#22c55e' :
            forecast.予測ステータス === '算出中' ? '#3b82f6' :
            '#ef4444'
          };">
            ${forecast.予測ステータス || '未処理'}
          </span>
        </td>
        <td>
          <button class="action-btn secondary detail-btn" data-id="${forecast.予測結果ID}">詳細</button>
          <button class="action-btn secondary order-btn" data-id="${forecast.予測結果ID}">発注</button>
        </td>
      </tr>
    `).join('');
  }

  // 予測結果グラフの描画
  function drawPredictionChart(data) {
    const canvas = container.querySelector('#prediction-chart');
    const ctx = canvas.getContext('2d');

    // キャンバスをクリア
    ctx.clearRect(0, 0, canvas.width, canvas.height);

    // グラフエリアの設定
    const padding = 60;
    const chartWidth = canvas.width - padding * 2;
    const chartHeight = canvas.height - padding * 2;

    // サンプルデータ（実際のデータがない場合）
    const sampleData = data.length > 0 ? data : [
      { date: '2024-01-01', actual: 120, predicted: 115 },
      { date: '2024-01-02', actual: 135, predicted: 140 },
      { date: '2024-01-03', actual: 98, predicted: 105 },
      { date: '2024-01-04', actual: 156, predicted: 150 },
      { date: '2024-01-05', actual: 142, predicted: 138 },
      { date: '2024-01-06', actual: 167, predicted: 165 },
      { date: '2024-01-07', actual: 189, predicted: 185 }
    ];

    // 最大値を取得
    const maxValue = Math.max(...sampleData.map(d => Math.max(d.actual || 0, d.predicted || 0))) * 1.1;

    // 軸の描画
    ctx.strokeStyle = '#4a5568';
    ctx.lineWidth = 1;
    ctx.beginPath();
    ctx.moveTo(padding, padding);
    ctx.lineTo(padding, canvas.height - padding);
    ctx.lineTo(canvas.width - padding, canvas.height - padding);
    ctx.stroke();

    // グリッドライン
    ctx.strokeStyle = '#2d3748';
    ctx.lineWidth = 0.5;
    for (let i = 1; i <= 5; i++) {
      const y = padding + (chartHeight / 5) * i;
      ctx.beginPath();
      ctx.moveTo(padding, y);
      ctx.lineTo(canvas.width - padding, y);
      ctx.stroke();
    }

    // データポイントの描画
    const pointSpacing = chartWidth / (sampleData.length - 1);

    // 実績データ（青線）
    ctx.strokeStyle = '#3b82f6';
    ctx.lineWidth = 2;
    ctx.beginPath();
    sampleData.forEach((point, index) => {
      const x = padding + index * pointSpacing;
      const y = canvas.height - padding - (point.actual / maxValue) * chartHeight;
      if (index === 0) {
        ctx.moveTo(x, y);
      } else {
        ctx.lineTo(x, y);
      }
    });
    ctx.stroke();

    // 予測データ（オレンジ線）
    ctx.strokeStyle = '#f59e0b';
    ctx.lineWidth = 2;
    ctx.beginPath();
    sampleData.forEach((point, index) => {
      const x = padding + index * pointSpacing;
      const y = canvas.height - padding - (point.predicted / maxValue) * chartHeight;
      if (index === 0) {
        ctx.moveTo(x, y);
      } else {
        ctx.lineTo(x, y);
      }
    });
    ctx.stroke();

    // 凡例
    ctx.fillStyle = '#e2e8f0';
    ctx.font = '12px sans-serif';
    ctx.fillText('実績値', padding + 20, 30);
    ctx.fillText('予測値', padding + 80, 30);

    ctx.fillStyle = '#3b82f6';
    ctx.fillRect(padding, 22, 15, 3);
    ctx.fillStyle = '#f59e0b';
    ctx.fillRect(padding + 60, 22, 15, 3);
  }

  // 比較チャートの描画
  function drawComparisonChart() {
    const canvas = container.querySelector('#comparison-chart');
    const ctx = canvas.getContext('2d');

    ctx.clearRect(0, 0, canvas.width, canvas.height);

    const padding = 60;
    const chartWidth = canvas.width - padding * 2;
    const chartHeight = canvas.height - padding * 2;

    // サンプル比較データ
    const categories = ['食品', '飲料', '日用品', '冷凍食品', 'その他'];
    const actualData = [450, 320, 280, 180, 150];
    const predictedData = [440, 335, 275, 185, 145];

    const maxValue = Math.max(...actualData, ...predictedData) * 1.1;
    const barWidth = chartWidth / categories.length / 3;

    // 軸の描画
    ctx.strokeStyle = '#4a5568';
    ctx.lineWidth = 1;
    ctx.beginPath();
    ctx.moveTo(padding, padding);
    ctx.lineTo(padding, canvas.height - padding);
    ctx.lineTo(canvas.width - padding, canvas.height - padding);
    ctx.stroke();

    // バーチャートの描画
    categories.forEach((category, index) => {
      const x = padding + (chartWidth / categories.length) * index + barWidth;

      // 実績バー
      const actualHeight = (actualData[index] / maxValue) * chartHeight;
      ctx.fillStyle = '#3b82f6';
      ctx.fillRect(x, canvas.height - padding - actualHeight, barWidth, actualHeight);

      // 予測バー
      const predictedHeight = (predictedData[index] / maxValue) * chartHeight;
      ctx.fillStyle = '#f59e0b';
      ctx.fillRect(x + barWidth + 5, canvas.height - padding - predictedHeight, barWidth, predictedHeight);

      // カテゴリ名
      ctx.fillStyle = '#e2e8f0';
      ctx.font = '11px sans-serif';
      ctx.fillText(category, x, canvas.height - padding + 15);
    });
  }

  // 影響要因分析の表示
  function renderFactorAnalysis() {
    const tbody = container.querySelector('#factor-tbody');
    const factors = [
      { factor: '気温', impact: '高', correlation: '0.75', description: '高温時に飲料の需要が増加' },
      { factor: '降水量', impact: '中', correlation: '-0.45', description: '雨天時に外出関連商品が減少' },
      { factor: '週末', impact: '高', correlation: '0.68', description: '土日に食品需要が増加' },
      { factor: 'イベント', impact: '中', correlation: '0.52', description: '地域イベント時に特定商品が増加' }
    ];

    tbody.innerHTML = factors.map(factor => `
      <tr>
        <td>${factor.factor}</td>
        <td>
          <span style="padding: 2px 6px; border-radius: 3px; font-size: 11px; background: ${
            factor.impact === '高' ? 'rgba(239, 68, 68, 0.1)' :
            factor.impact === '中' ? 'rgba(245, 158, 11, 0.1)' :
            'rgba(34, 197, 94, 0.1)'
          }; color: ${
            factor.impact === '高' ? '#ef4444' :
            factor.impact === '中' ? '#f59e0b' :
            '#22c55e'
          };">
            ${factor.impact}
          </span>
        </td>
        <td>${factor.correlation}</td>
        <td>${factor.description}</td>
      </tr>
    `).join('');
  }

  // 予測実行処理
  async function executePrediction() {
    const storeId = container.querySelector('#store-select').value;
    const category = container.querySelector('#category-select').value;
    const startDate = container.querySelector('#start-date').value;
    const endDate = container.querySelector('#end-date').value;
    const seasonalModel = container.querySelector('#seasonal-model').checked;
    const eventModel = container.querySelector('#event-model').checked;
    const weatherModel = container.querySelector('#weather-model').checked;

    // バリデーション
    if (!storeId) {
      alert('店舗を選択してください');
      return;
    }
    if (!category) {
      alert('商品カテゴリを選択してください');
      return;
    }
    if (!startDate || !endDate) {
      alert('予測期間を設定してください');
      return;
    }
    if (new Date(startDate) >= new Date(endDate)) {
      alert('開始日は終了日より前の日付を入力してください');
      return;
    }
    if (new Date(startDate) < new Date()) {
      alert('開始日は現在日以降の日付を設定してください');
      return;
    }
    if (!seasonalModel && !eventModel && !weatherModel) {
      alert('予測モデルを選択してください');
      return;
    }

    // ローディング表示
    container.querySelector('#loading-overlay').classList.remove('hidden');

    try {
      // 予測結果を生成（実際のAPIがない場合のサンプル）
      await new Promise(resolve => setTimeout(resolve, 2000)); // 2秒待機

      // 商品データを取得
      const productTable = tables.find(t => t.tableName === '商品マスタ');
      const products = productTable ? productTable.records.filter(p => 
        p.有効フラグ && p.AI予測対象フラグ
      ) : [];

      // 予測結果データを生成
      const forecastResults = products.slice(0, 10).map(product => ({
        予測結果ID: `pred-${Date.now()}-${Math.random().toString(36).substr(2, 9)}`,
        店舗ID: storeId,
        商品ID: product.商品ID,
        商品コード: product.商品コード,
        商品名: product.商品名,
        予測対象日: startDate,
        予測数量: Math.floor(Math.random() * 200) + 50,
        推奨発注数量: Math.floor(Math.random() * 180) + 40,
        予測精度: Math.floor(Math.random() * 30) + 70,
        予測ステータス: '完了',
        予測モデルバージョン: 'v2.1.0',
        発注済フラグ: false
      }));

      allProductForecasts = forecastResults;

      // 予測精度指標を更新
      const avgAccuracy = Math.floor(forecastResults.reduce((sum, f) => sum + f.予測精度, 0) / forecastResults.length);
      container.querySelector('#accuracy-value').textContent = `${avgAccuracy}%`;
      container.querySelector('#confidence-interval').textContent = `±${Math.floor(avgAccuracy * 0.1)}%`;
      container.querySelector('#model-version').textContent = 'AI予測モデル v2.1.0';

      // 外部要因情報を更新
      container.querySelector('#events-list').textContent = 'セール期間、地域祭り';
      container.querySelector('#weather-forecast').textContent = '晴れ時々曇り、最高気温25℃';

      // グラフを描画
      drawPredictionChart([]);
      drawComparisonChart();

      // 影響要因分析を表示
      renderFactorAnalysis();

      // 商品別予測一覧を表示
      renderProductForecasts(allProductForecasts);

      // 結果エリアを表示
      container.querySelector('#prediction-results').classList.remove('hidden');
      container.querySelector('#product-forecast-list').classList.remove('hidden');

    } catch (error) {
      alert('予測処理中にエラーが発生しました: ' + error.message);
    } finally {
      container.querySelector('#loading-overlay').classList.add('hidden');
    }
  }

  // CSVエクスポート
  function exportToCSV() {
    if (allProductForecasts.length === 0) {
      alert('エクスポートするデータがありません');
      return;
    }

    const headers = ['商品コード', '商品名', '予測対象日', '予測数量', '推奨発注数量', '予測精度', 'ステータス'];
    const csvContent = '\uFEFF' + [
      headers.join(','),
      ...allProductForecasts.map(forecast => [
        forecast.商品コード || '',
        `"${forecast.商品名 || ''}"`,
        forecast.予測対象日 || '',
        forecast.予測数量 || 0,
        forecast.推奨発注数量 || 0,
        `${forecast.予測精度 || 0}%`,
        forecast.予測ステータス || ''
      ].join(','))
    ].join('\n');

    const blob = new Blob([csvContent], { type: 'text/csv;charset=utf-8;' });
    const link = document.createElement('a');
    link.href = URL.createObjectURL(blob);
    link.download = `需要予測結果_${new Date().toISOString().split('T')[0]}.csv`;
    link.click();
  }

  // 商品検索
  function searchProducts() {
    const keyword = container.querySelector('#product-search').value.toLowerCase();
    const filtered = allProductForecasts.filter(forecast => 
      (forecast.商品名 || '').toLowerCase().includes(keyword) ||
      (forecast.商品コード || '').toLowerCase().includes(keyword)
    );
    renderProductForecasts(filtered);
  }

  // 初期化
  loadStores();

  // 今日の日付を開始日に設定
  const today = new Date().toISOString().split('T')[0];
  container.querySelector('#start-date').value = today;

  // 1週間後を終了日に設定
  const nextWeek = new Date();
  nextWeek.setDate(nextWeek.getDate() + 7);
  container.querySelector('#end-date').value = nextWeek.toISOString().split('T')[0];

  // イベントリスナー
  container.querySelector('#btn-predict').addEventListener('click', executePrediction);
  container.querySelector('#btn-product-search').addEventListener('click', searchProducts);
  container.querySelector('#btn-export-csv').addEventListener('click', exportToCSV);

  // 商品検索のEnterキー対応
  container.querySelector('#product-search').addEventListener('keypress', (e) => {
    if (e.key === 'Enter') {
      searchProducts();
    }
  });

  // 行レベル操作のイベントデリゲーション
  container.addEventListener('click', (e) => {
    const detailBtn = e.target.closest('.detail-btn');
    const orderBtn = e.target.closest('.order-btn');

    if (detailBtn) {
      const forecastId = detailBtn.dataset.id;
      // 詳細画面への遷移（実装例）
      alert(`予測結果詳細: ${forecastId}`);
    }

    if (orderBtn) {
      const forecastId = orderBtn.dataset.id;
      // 発注画面への遷移
      window.showScreen('scr-1778591852463'); // 発注管理画面
    }
  });
}

function(container, apiUrl, tables) {
  let currentProducts = [];
  let currentStore = null;
  let orderingProduct = null;

  // 店舗データを取得してドロップダウンに設定
  async function loadStores() {
    try {
      const stores = await window.aivicApi.list(1); // 店舗マスタのインデックス
      const storeSelect = container.querySelector('#store-select');
      storeSelect.innerHTML = '<option value="">店舗を選択してください</option>';

      if (stores) {
        stores.forEach(store => {
          const option = document.createElement('option');
          option.value = store.id;
          option.textContent = `${store.店舗コード || ''} ${store.店舗名 || ''}`;
          storeSelect.appendChild(option);
        });
      }
    } catch (error) {
      console.error('店舗データの取得に失敗しました:', error);
    }
  }

  // 商品一覧の再描画
  function renderProducts(products) {
    const tbody = container.querySelector('#product-tbody');

    if (!currentStore) {
      tbody.innerHTML = '<tr><td colspan="8" style="text-align: center; color: var(--text-muted); padding: 40px;">店舗を選択してください</td></tr>';
      return;
    }

    if (!products || products.length === 0) {
      tbody.innerHTML = '<tr><td colspan="8" style="text-align: center; color: var(--text-muted); padding: 40px;">該当する商品が見つかりません</td></tr>';
      return;
    }

    tbody.innerHTML = products.map(product => {
      const currentStock = Math.floor(Math.random() * 100) + 10; // 仮の在庫数
      const predictedDemand = Math.floor(Math.random() * 50) + 5; // 仮の予測需要量
      const recommendedOrder = Math.max(0, predictedDemand - currentStock); // 推奨発注量

      return `
        <tr data-id="${product.id}">
          <td>${product.商品コード || ''}</td>
          <td>${product.商品名 || ''}</td>
          <td style="text-align: right;">${currentStock}</td>
          <td style="text-align: right;">${predictedDemand}</td>
          <td style="text-align: right;">${recommendedOrder}</td>
          <td>
            <input type="number" 
                   class="input order-quantity" 
                   data-product-id="${product.id}"
                   value="${recommendedOrder}" 
                   min="0" 
                   style="width: 80px; text-align: right;">
          </td>
          <td>
            <input type="text" 
                   class="input order-reason" 
                   data-product-id="${product.id}"
                   placeholder="発注理由" 
                   style="width: 120px;">
          </td>
          <td>
            <button class="action-btn order-btn" data-product-id="${product.id}">発注</button>
            <button class="action-btn secondary adjust-btn" data-product-id="${product.id}">調整</button>
          </td>
        </tr>
      `;
    }).join('');
  }

  // 需要予測結果の表示
  function renderPredictionResults(storeId) {
    const predictionArea = container.querySelector('#prediction-area');

    if (!storeId) {
      predictionArea.innerHTML = '<div style="color: var(--text-muted); text-align: center; padding: 20px;">店舗を選択すると需要予測結果が表示されます</div>';
      return;
    }

    // 仮の予測結果データ
    const totalPrediction = Math.floor(Math.random() * 1000) + 500;
    const accuracy = Math.floor(Math.random() * 20) + 80;

    predictionArea.innerHTML = `
      <div style="display: flex; gap: 24px; justify-content: center;">
        <div style="text-align: center;">
          <div style="font-size: 24px; font-weight: bold; color: var(--primary);">${totalPrediction}</div>
          <div style="color: var(--text-muted); font-size: 14px;">総予測需要量</div>
        </div>
        <div style="text-align: center;">
          <div style="font-size: 24px; font-weight: bold; color: var(--primary);">${accuracy}%</div>
          <div style="color: var(--text-muted); font-size: 14px;">予測精度</div>
        </div>
        <div style="text-align: center;">
          <div style="font-size: 24px; font-weight: bold; color: var(--primary);">${new Date().toLocaleDateString()}</div>
          <div style="color: var(--text-muted); font-size: 14px;">最終更新</div>
        </div>
      </div>
    `;
  }

  // 商品データの取得とフィルタリング
  async function loadAndFilterProducts() {
    try {
      const allProducts = await window.aivicApi.list(2); // 商品マスタのインデックス
      if (!allProducts) return;

      let filteredProducts = allProducts.filter(p => p.有効フラグ !== false);

      // カテゴリフィルタ
      const categoryFilter = container.querySelector('#category-select').value;
      if (categoryFilter) {
        filteredProducts = filteredProducts.filter(p => 
          (p.商品カテゴリ || '').includes(categoryFilter)
        );
      }

      // 商品名検索
      const searchKeyword = container.querySelector('#product-search').value.trim();
      if (searchKeyword) {
        filteredProducts = filteredProducts.filter(p => 
          (p.商品名 || '').includes(searchKeyword) || 
          (p.商品コード || '').includes(searchKeyword)
        );
      }

      currentProducts = filteredProducts;
      renderProducts(filteredProducts);
    } catch (error) {
      console.error('商品データの取得に失敗しました:', error);
    }
  }

  // 発注処理
  async function processOrder(productId) {
    const quantityInput = container.querySelector(`input.order-quantity[data-product-id="${productId}"]`);
    const reasonInput = container.querySelector(`input.order-reason[data-product-id="${productId}"]`);

    const quantity = parseInt(quantityInput.value);
    const reason = reasonInput.value.trim();

    // バリデーション
    if (isNaN(quantity)) {
      alert('発注量は数値で入力してください');
      quantityInput.focus();
      return;
    }

    if (quantity < 0) {
      alert('発注量は正の数値を入力してください');
      quantityInput.focus();
      return;
    }

    if (quantity === 0) {
      alert('発注量は1以上を入力してください');
      quantityInput.focus();
      return;
    }

    if (!quantity) {
      alert('発注量を入力してください');
      quantityInput.focus();
      return;
    }

    const product = currentProducts.find(p => p.id === productId);
    if (!product) return;

    // 発注確認モーダルを表示
    const modal = container.querySelector('#order-modal');
    const content = container.querySelector('#order-confirm-content');

    content.innerHTML = `
      <div style="margin-bottom: 12px;"><strong>商品:</strong> ${product.商品名}</div>
      <div style="margin-bottom: 12px;"><strong>発注量:</strong> ${quantity}個</div>
      <div style="margin-bottom: 12px;"><strong>発注理由:</strong> ${reason || '(未入力)'}</div>
      <div style="margin-bottom: 12px;"><strong>店舗:</strong> ${container.querySelector('#store-select option:checked').textContent}</div>
    `;

    orderingProduct = { productId, quantity, reason, product };
    modal.classList.remove('hidden');
  }

  // 発注確定処理
  async function confirmOrder() {
    if (!orderingProduct) return;

    try {
      const orderData = {
        店舗ID: currentStore,
        商品ID: orderingProduct.productId,
        発注日: new Date().toISOString(),
        納期予定日: new Date(Date.now() + 7 * 24 * 60 * 60 * 1000).toISOString(), // 7日後
        発注数量: orderingProduct.quantity,
        発注単価: orderingProduct.product.単価 || 0,
        発注金額: orderingProduct.quantity * (orderingProduct.product.単価 || 0),
        発注方法: orderingProduct.reason ? 'AI推奨修正' : 'AI推奨採用',
        発注ステータス: '発注済',
        仕入先ID: orderingProduct.product.仕入先ID || '',
        発注理由: orderingProduct.reason || '',
        自動発注フラグ: false,
        作成者ID: 'current-user-id',
        更新者ID: 'current-user-id'
      };

      const saved = await window.aivicApi.save(7, orderData); // 発注データのインデックス

      if (saved) {
        alert('発注が完了しました');

        // 発注量と理由をクリア
        const quantityInput = container.querySelector(`input.order-quantity[data-product-id="${orderingProduct.productId}"]`);
        const reasonInput = container.querySelector(`input.order-reason[data-product-id="${orderingProduct.productId}"]`);
        if (quantityInput) quantityInput.value = '0';
        if (reasonInput) reasonInput.value = '';
      } else {
        alert('発注処理に失敗しました');
      }
    } catch (error) {
      console.error('発注処理エラー:', error);
      alert('発注処理中にエラーが発生しました');
    }

    // モーダルを閉じる
    container.querySelector('#order-modal').classList.add('hidden');
    orderingProduct = null;
  }

  // CSVエクスポート
  async function exportCSV() {
    try {
      const products = await window.aivicApi.list(2);
      if (!products || products.length === 0) {
        alert('エクスポートするデータがありません');
        return;
      }

      const headers = ['商品コード', '商品名', '商品カテゴリ', '単価', '販売価格', '発注単位', '最小発注数量', 'リードタイム日数'];
      const csvContent = '\uFEFF' + [
        headers.join(','),
        ...products.map(p => [
          p.商品コード || '',
          p.商品名 || '',
          p.商品カテゴリ || '',
          p.単価 || 0,
          p.販売価格 || 0,
          p.発注単位 || 1,
          p.最小発注数量 || 1,
          p.リードタイム日数 || 0
        ].map(field => `"${field}"`).join(','))
      ].join('\n');

      const blob = new Blob([csvContent], { type: 'text/csv;charset=utf-8;' });
      const link = document.createElement('a');
      link.href = URL.createObjectURL(blob);
      link.download = `商品一覧_${new Date().toISOString().split('T')[0]}.csv`;
      link.click();
    } catch (error) {
      console.error('CSVエクスポートエラー:', error);
      alert('CSVエクスポートに失敗しました');
    }
  }

  // イベントリスナーの設定

  // 店舗選択
  container.querySelector('#store-select').addEventListener('change', (e) => {
    currentStore = e.target.value;
    renderPredictionResults(currentStore);
    if (currentStore) {
      loadAndFilterProducts();
    } else {
      renderProducts([]);
    }
  });

  // 検索ボタン
  container.querySelector('#btn-search').addEventListener('click', () => {
    const dateStart = container.querySelector('#date-start').value;
    const dateEnd = container.querySelector('#date-end').value;

    // 日付バリデーション
    if (dateStart && dateEnd && new Date(dateStart) > new Date(dateEnd)) {
      alert('終了日は開始日以降の日付を入力してください');
      return;
    }

    if (currentStore) {
      loadAndFilterProducts();
    }
  });

  // CSVエクスポートボタン
  container.querySelector('#btn-csv-export').addEventListener('click', exportCSV);

  // 商品テーブルのイベントデリゲーション
  container.addEventListener('click', async (e) => {
    // 発注ボタン
    const orderBtn = e.target.closest('.order-btn');
    if (orderBtn) {
      const productId = orderBtn.dataset.productId;
      await processOrder(productId);
      return;
    }

    // 調整ボタン（推奨発注量を再設定）
    const adjustBtn = e.target.closest('.adjust-btn');
    if (adjustBtn) {
      const productId = adjustBtn.dataset.productId;
      const quantityInput = container.querySelector(`input.order-quantity[data-product-id="${productId}"]`);
      const currentStock = Math.floor(Math.random() * 100) + 10;
      const predictedDemand = Math.floor(Math.random() * 50) + 5;
      const recommendedOrder = Math.max(0, predictedDemand - currentStock);
      quantityInput.value = recommendedOrder;
      return;
    }
  });

  // モーダルのイベントリスナー
  container.querySelector('#btn-cancel-order').addEventListener('click', () => {
    container.querySelector('#order-modal').classList.add('hidden');
    orderingProduct = null;
  });

  container.querySelector('#btn-confirm-order').addEventListener('click', confirmOrder);

  // 初期化処理
  loadStores();
  renderProducts([]);
  renderPredictionResults(null);
}

function(container, apiUrl, tables) {
  const tbody = container.querySelector('#log-tbody');
  let allLogs = [];
  let autoRefreshInterval = null;

  // ステータス表示用のヘルパー関数
  function getStatusBadge(status) {
    const statusMap = {
      '成功': { color: '#22c55e', bg: 'rgba(34, 197, 94, 0.1)' },
      '失敗': { color: '#ef4444', bg: 'rgba(239, 68, 68, 0.1)' },
      '実行中': { color: '#f59e0b', bg: 'rgba(245, 158, 11, 0.1)' },
      '警告': { color: '#f59e0b', bg: 'rgba(245, 158, 11, 0.1)' }
    };
    const style = statusMap[status] || { color: 'var(--text-muted)', bg: 'var(--bg-card)' };
    return `<span style="background: ${style.bg}; color: ${style.color}; padding: 4px 8px; border-radius: 4px; font-size: 12px; font-weight: 500;">${status}</span>`;
  }

  // ログレベル判定
  function getLogLevel(status, errorCount) {
    if (status === '失敗' || errorCount > 0) return 'ERROR';
    if (status === '警告') return 'WARN';
    return 'INFO';
  }

  // 日時フォーマット
  function formatDateTime(dateStr) {
    if (!dateStr) return '-';
    const date = new Date(dateStr);
    return date.toLocaleString('ja-JP');
  }

  // 店舗名取得
  function getStoreName(storeId) {
    if (!storeId || !tables[1]) return '-';
    const store = tables[1].records?.find(s => s.店舗ID === storeId);
    return store ? store.店舗名 : '-';
  }

  // テーブル再描画関数
  function renderRows(rows) {
    tbody.innerHTML = rows.map(r => `
      <tr data-id="${r.ログID}">
        <td>${formatDateTime(r.収集開始日時)}</td>
        <td>${r.データ種別 || '-'}</td>
        <td>${r.データソース || '-'}</td>
        <td>${getStoreName(r.店舗ID)}</td>
        <td>${getStatusBadge(r.処理ステータス)}</td>
        <td style="text-align: right;">${(r.収集件数 || 0).toLocaleString()}</td>
        <td style="text-align: right;">${(r.エラー件数 || 0).toLocaleString()}</td>
        <td style="text-align: right;">${r.処理時間秒 || 0}秒</td>
        <td style="text-align: right;">${r.データ品質スコア || '-'}</td>
        <td>
          <button class="action-btn secondary detail-btn" data-id="${r.ログID}">詳細</button>
          ${r.処理ステータス === '失敗' ? `<button class="action-btn secondary retry-btn" data-id="${r.ログID}">再実行</button>` : ''}
        </td>
      </tr>
    `).join('');

    updateSummary(rows);
    updateErrorIndicator(rows);
  }

  // サマリー更新
  function updateSummary(rows) {
    const totalCount = rows.reduce((sum, r) => sum + (r.収集件数 || 0), 0);
    const successCount = rows.filter(r => r.処理ステータス === '成功').reduce((sum, r) => sum + (r.収集件数 || 0), 0);
    const errorCount = rows.reduce((sum, r) => sum + (r.エラー件数 || 0), 0);
    const lastExecution = rows.length > 0 ? formatDateTime(rows[0].収集開始日時) : '-';

    container.querySelector('#total-count').textContent = totalCount.toLocaleString();
    container.querySelector('#success-count').textContent = successCount.toLocaleString();
    container.querySelector('#error-count').textContent = errorCount.toLocaleString();
    container.querySelector('#last-execution').textContent = lastExecution;
  }

  // エラーインジケーター更新
  function updateErrorIndicator(rows) {
    const hasErrors = rows.some(r => r.処理ステータス === '失敗' || (r.エラー件数 || 0) > 0);
    const indicator = container.querySelector('#error-indicator');
    if (hasErrors) {
      indicator.classList.remove('hidden');
    } else {
      indicator.classList.add('hidden');
    }
  }

  // フィルタリング関数
  function applyFilters() {
    const datasource = container.querySelector('#filter-datasource').value;
    const loglevel = container.querySelector('#filter-loglevel').value;
    const startDate = container.querySelector('#filter-start-date').value;
    const endDate = container.querySelector('#filter-end-date').value;

    // 日付範囲バリデーション
    if (startDate && endDate && new Date(startDate) > new Date(endDate)) {
      alert('開始日は終了日より前の日付を設定してください');
      return;
    }

    let filtered = allLogs.filter(log => {
      // データソースフィルター
      if (datasource && log.データソース !== datasource) return false;

      // ログレベルフィルター
      if (loglevel) {
        const logLevel = getLogLevel(log.処理ステータス, log.エラー件数);
        if (logLevel !== loglevel) return false;
      }

      // 日付範囲フィルター
      if (startDate && log.収集開始日時 && new Date(log.収集開始日時) < new Date(startDate)) return false;
      if (endDate && log.収集開始日時 && new Date(log.収集開始日時) > new Date(endDate)) return false;

      return true;
    });

    renderRows(filtered);
  }

  // CSVエクスポート
  function exportCSV() {
    const headers = ['収集日時', 'データ種別', 'データソース', '店舗名', 'ステータス', '収集件数', 'エラー件数', '処理時間', '品質スコア'];
    const csvContent = '\uFEFF' + [
      headers.join(','),
      ...allLogs.map(log => [
        formatDateTime(log.収集開始日時),
        log.データ種別 || '',
        log.データソース || '',
        getStoreName(log.店舗ID),
        log.処理ステータス || '',
        log.収集件数 || 0,
        log.エラー件数 || 0,
        (log.処理時間秒 || 0) + '秒',
        log.データ品質スコア || ''
      ].map(field => `"${field}"`).join(','))
    ].join('\n');

    const blob = new Blob([csvContent], { type: 'text/csv;charset=utf-8;' });
    const link = document.createElement('a');
    link.href = URL.createObjectURL(blob);
    link.download = `data_collection_logs_${new Date().toISOString().split('T')[0]}.csv`;
    link.click();
  }

  // ログ詳細表示
  function showLogDetail(logId) {
    const log = allLogs.find(l => l.ログID === logId);
    if (!log) return;

    const modalBody = container.querySelector('#modal-content-body');
    modalBody.innerHTML = `
      <div style="display: grid; gap: 16px;">
        <div style="display: grid; grid-template-columns: 150px 1fr; gap: 8px; align-items: center;">
          <strong>ログID:</strong><span>${log.ログID}</span>
          <strong>データ種別:</strong><span>${log.データ種別 || '-'}</span>
          <strong>データソース:</strong><span>${log.データソース || '-'}</span>
          <strong>店舗:</strong><span>${getStoreName(log.店舗ID)}</span>
          <strong>収集開始日時:</strong><span>${formatDateTime(log.収集開始日時)}</span>
          <strong>収集終了日時:</strong><span>${formatDateTime(log.収集終了日時)}</span>
          <strong>処理ステータス:</strong><span>${getStatusBadge(log.処理ステータス)}</span>
          <strong>対象期間:</strong><span>${formatDateTime(log.対象期間開始日)} ～ ${formatDateTime(log.対象期間終了日)}</span>
          <strong>収集件数:</strong><span>${(log.収集件数 || 0).toLocaleString()}件</span>
          <strong>エラー件数:</strong><span>${(log.エラー件数 || 0).toLocaleString()}件</span>
          <strong>処理時間:</strong><span>${log.処理時間秒 || 0}秒</span>
          <strong>データ品質スコア:</strong><span>${log.データ品質スコア || '-'}</span>
        </div>
        ${log.エラーメッセージ ? `
          <div>
            <strong style="color: var(--text);">エラーメッセージ:</strong>
            <div style="background: var(--bg-main); border: 1px solid var(--border); border-radius: 4px; padding: 12px; margin-top: 8px; font-family: monospace; white-space: pre-wrap; max-height: 200px; overflow-y: auto;">${log.エラーメッセージ}</div>
          </div>
        ` : ''}
        ${log.備考 ? `
          <div>
            <strong style="color: var(--text);">備考:</strong>
            <div style="margin-top: 8px;">${log.備考}</div>
          </div>
        ` : ''}
      </div>
    `;

    container.querySelector('#log-detail-modal').classList.remove('hidden');
  }

  // エラーログ再実行
  async function retryErrorLog(logId) {
    if (!confirm('このログの処理を再実行しますか？')) return;

    try {
      // 再実行処理をシミュレート
      const log = allLogs.find(l => l.ログID === logId);
      if (log) {
        const updated = await window.aivicApi.update(12, logId, {
          処理ステータス: '成功',
          エラー件数: 0,
          エラーメッセージ: null,
          再実行フラグ: false,
          更新日時: new Date().toISOString()
        });

        if (updated) {
          alert('再実行が完了しました');
          loadLogs();
        } else {
          alert('再実行に失敗しました');
        }
      }
    } catch (error) {
      alert('再実行に失敗しました: ' + error.message);
    }
  }

  // 自動更新設定
  function toggleAutoRefresh() {
    const isEnabled = container.querySelector('#auto-refresh-toggle').checked;

    if (isEnabled) {
      autoRefreshInterval = setInterval(() => {
        loadLogs();
      }, 30000); // 30秒間隔
    } else {
      if (autoRefreshInterval) {
        clearInterval(autoRefreshInterval);
        autoRefreshInterval = null;
      }
    }
  }

  // ログデータ読み込み
  async function loadLogs() {
    try {
      const logs = await window.aivicApi.list(12);
      if (logs) {
        allLogs = logs.sort((a, b) => new Date(b.収集開始日時) - new Date(a.収集開始日時));
        renderRows(allLogs);
      }
    } catch (error) {
      console.error('ログ読み込みエラー:', error);
    }
  }

  // 初期データ表示
  allLogs = (tables[12]?.records || []).sort((a, b) => new Date(b.収集開始日時) - new Date(a.収集開始日時));
  renderRows(allLogs);

  // 最新データ読み込み
  loadLogs();

  // イベントリスナー登録
  container.querySelector('#btn-search').addEventListener('click', applyFilters);
  container.querySelector('#btn-export').addEventListener('click', exportCSV);
  container.querySelector('#auto-refresh-toggle').addEventListener('change', toggleAutoRefresh);

  // モーダル関連
  container.querySelector('#btn-close-modal').addEventListener('click', () => {
    container.querySelector('#log-detail-modal').classList.add('hidden');
  });

  container.querySelector('#btn-alert-settings').addEventListener('click', () => {
    container.querySelector('#alert-settings-modal').classList.remove('hidden');
  });

  container.querySelector('#btn-close-alert-modal').addEventListener('click', () => {
    container.querySelector('#alert-settings-modal').classList.add('hidden');
  });

  container.querySelector('#btn-error-details').addEventListener('click', () => {
    const errorLogs = allLogs.filter(log => log.処理ステータス === '失敗' || (log.エラー件数 || 0) > 0);
    if (errorLogs.length > 0) {
      showLogDetail(errorLogs[0].ログID);
    }
  });

  // 行レベル操作のイベントデリゲーション
  container.addEventListener('click', async (e) => {
    const detailBtn = e.target.closest('.detail-btn');
    const retryBtn = e.target.closest('.retry-btn');

    if (detailBtn) {
      showLogDetail(detailBtn.dataset.id);
    }

    if (retryBtn) {
      await retryErrorLog(retryBtn.dataset.id);
    }
  });

  // モーダル外クリックで閉じる
  container.querySelector('#log-detail-modal').addEventListener('click', (e) => {
    if (e.target.classList.contains('modal')) {
      container.querySelector('#log-detail-modal').classList.add('hidden');
    }
  });

  container.querySelector('#alert-settings-modal').addEventListener('click', (e) => {
    if (e.target.classList.contains('modal')) {
      container.querySelector('#alert-settings-modal').classList.add('hidden');
    }
  });
}

function(container, apiUrl, tables) {
  const ITEMS_PER_PAGE = 20;
  let currentPage = 1;
  let filteredData = [];
  let allUsers = [];

  // ユーザー一覧を取得してセレクトボックスに設定
  async function loadUsers() {
    try {
      const users = await window.aivicApi.list(0); // ログインユーザーテーブル
      if (users) {
        allUsers = users;
        const userSelect = container.querySelector('#filter-user');
        userSelect.innerHTML = '<option value="">全ユーザー</option>';
        users.forEach(user => {
          userSelect.innerHTML += `<option value="${user.ユーザーID}">${user.ユーザー名}</option>`;
        });
      }
    } catch (error) {
      console.error('ユーザー一覧の取得に失敗しました:', error);
    }
  }

  // 操作履歴テーブルの再描画
  function renderRows(rows) {
    const tbody = container.querySelector('#history-tbody');
    const startIndex = (currentPage - 1) * ITEMS_PER_PAGE;
    const endIndex = startIndex + ITEMS_PER_PAGE;
    const pageRows = rows.slice(startIndex, endIndex);

    tbody.innerHTML = pageRows.map(row => {
      const user = allUsers.find(u => u.ユーザーID === row.ユーザーID);
      const userName = user ? user.ユーザー名 : row.ユーザーID || '';
      const operationDate = row.操作日時 ? new Date(row.操作日時).toLocaleString('ja-JP') : '';
      const processingTime = row.処理時間 ? `${row.処理時間}ms` : '';

      return `
        <tr data-id="${row.操作履歴ID}">
          <td>${operationDate}</td>
          <td>${userName}</td>
          <td>${row.操作種別 || ''}</td>
          <td>${row.操作画面 || ''}</td>
          <td>${row.IPアドレス || ''}</td>
          <td><span class="status-badge ${getResultClass(row.処理結果)}">${row.処理結果 || ''}</span></td>
          <td>${processingTime}</td>
          <td>
            <button class="action-btn secondary detail-btn" data-id="${row.操作履歴ID}">詳細</button>
          </td>
        </tr>
      `;
    }).join('');

    updatePagination(rows.length);
    updateResultsInfo(rows.length);
  }

  function getResultClass(result) {
    switch(result) {
      case '成功': return 'success';
      case '失敗': return 'error';
      case 'エラー': return 'error';
      default: return '';
    }
  }

  function updatePagination(totalItems) {
    const totalPages = Math.ceil(totalItems / ITEMS_PER_PAGE);
    const pageInfo = container.querySelector('#page-info');
    const prevBtn = container.querySelector('#btn-prev');
    const nextBtn = container.querySelector('#btn-next');

    pageInfo.textContent = `${currentPage} / ${totalPages}`;
    prevBtn.disabled = currentPage <= 1;
    nextBtn.disabled = currentPage >= totalPages;
  }

  function updateResultsInfo(totalItems) {
    const info = container.querySelector('#search-results-info');
    info.textContent = `${totalItems}件の操作履歴が見つかりました`;
  }

  // フィルタリング処理
  async function applyFilters() {
    try {
      const allRows = await window.aivicApi.list(12); // システム操作履歴テーブル
      if (!allRows) return;

      const startDate = container.querySelector('#filter-start-date').value;
      const endDate = container.querySelector('#filter-end-date').value;
      const userId = container.querySelector('#filter-user').value;
      const operationType = container.querySelector('#filter-operation-type').value;
      const screenName = container.querySelector('#filter-screen-name').value.toLowerCase();
      const ipAddress = container.querySelector('#filter-ip-address').value.toLowerCase();
      const result = container.querySelector('#filter-result').value;

      // 日付範囲バリデーション
      if (startDate && endDate && new Date(startDate) > new Date(endDate)) {
        alert('開始日が終了日より後の日付になっています。正しい日付範囲を入力してください。');
        return;
      }

      // IPアドレス形式バリデーション
      if (ipAddress && !isValidIpAddress(ipAddress)) {
        alert('不正なIPアドレス形式です。正しい形式で入力してください。');
        return;
      }

      filteredData = allRows.filter(row => {
        // 日付範囲フィルター
        if (startDate || endDate) {
          const rowDate = row.操作日時 ? new Date(row.操作日時).toISOString().split('T')[0] : '';
          if (startDate && rowDate < startDate) return false;
          if (endDate && rowDate > endDate) return false;
        }

        // ユーザーフィルター
        if (userId && row.ユーザーID !== userId) return false;

        // 操作種別フィルター
        if (operationType && row.操作種別 !== operationType) return false;

        // 画面名フィルター
        if (screenName && !(row.操作画面 || '').toLowerCase().includes(screenName)) return false;

        // IPアドレスフィルター
        if (ipAddress && !(row.IPアドレス || '').toLowerCase().includes(ipAddress)) return false;

        // 処理結果フィルター
        if (result && row.処理結果 !== result) return false;

        return true;
      });

      currentPage = 1;
      renderRows(filteredData);

      if (filteredData.length === 0) {
        container.querySelector('#search-results-info').textContent = '該当する操作履歴が見つかりませんでした';
      }
    } catch (error) {
      console.error('検索処理でエラーが発生しました:', error);
      alert('検索処理でエラーが発生しました');
    }
  }

  function isValidIpAddress(ip) {
    const ipRegex = /^(?:(?:25[0-5]|2[0-4][0-9]|[01]?[0-9][0-9]?)\.){3}(?:25[0-5]|2[0-4][0-9]|[01]?[0-9][0-9]?)$/;
    return ipRegex.test(ip);
  }

  // 検索条件クリア
  function clearFilters() {
    container.querySelector('#filter-start-date').value = '';
    container.querySelector('#filter-end-date').value = '';
    container.querySelector('#filter-user').value = '';
    container.querySelector('#filter-operation-type').value = '';
    container.querySelector('#filter-screen-name').value = '';
    container.querySelector('#filter-ip-address').value = '';
    container.querySelector('#filter-result').value = '';

    currentPage = 1;
    applyFilters();
  }

  // CSV出力
  async function exportToCsv() {
    try {
      const allRows = await window.aivicApi.list(12);
      if (!allRows || allRows.length === 0) {
        alert('出力するデータがありません');
        return;
      }

      // 大量データの場合の警告
      if (allRows.length > 100000) {
        alert('データ量が多すぎるため、CSV出力に失敗しました。検索条件を絞り込んでから再度お試しください。');
        return;
      }

      const headers = ['操作日時', 'ユーザーID', 'ユーザー名', '操作種別', '操作画面', '操作対象テーブル', '操作対象ID', '操作内容', 'IPアドレス', 'ユーザーエージェント', '処理結果', 'エラーメッセージ', '処理時間'];

      const csvContent = [
        headers.join(','),
        ...allRows.map(row => {
          const user = allUsers.find(u => u.ユーザーID === row.ユーザーID);
          const userName = user ? user.ユーザー名 : '';
          const operationDate = row.操作日時 ? new Date(row.操作日時).toLocaleString('ja-JP') : '';

          return [
            `"${operationDate}"`,
            `"${row.ユーザーID || ''}"`,
            `"${userName}"`,
            `"${row.操作種別 || ''}"`,
            `"${row.操作画面 || ''}"`,
            `"${row.操作対象テーブル || ''}"`,
            `"${row.操作対象ID || ''}"`,
            `"${(row.操作内容 || '').replace(/"/g, '""')}"`,
            `"${row.IPアドレス || ''}"`,
            `"${(row.ユーザーエージェント || '').replace(/"/g, '""')}"`,
            `"${row.処理結果 || ''}"`,
            `"${(row.エラーメッセージ || '').replace(/"/g, '""')}"`,
            `"${row.処理時間 || ''}"`
          ].join(',');
        })
      ].join('\n');

      const blob = new Blob(['\uFEFF' + csvContent], { type: 'text/csv;charset=utf-8;' });
      const link = document.createElement('a');
      link.href = URL.createObjectURL(blob);
      link.download = `システム操作履歴_${new Date().toISOString().split('T')[0]}.csv`;
      link.click();
    } catch (error) {
      console.error('CSV出力でエラーが発生しました:', error);
      alert('CSV出力でエラーが発生しました');
    }
  }

  // 詳細モーダル表示
  function showDetailModal(historyId) {
    const history = filteredData.find(h => h.操作履歴ID === historyId);
    if (!history) return;

    const user = allUsers.find(u => u.ユーザーID === history.ユーザーID);
    const userName = user ? user.ユーザー名 : history.ユーザーID || '';
    const operationDate = history.操作日時 ? new Date(history.操作日時).toLocaleString('ja-JP') : '';

    container.querySelector('#detail-datetime').textContent = operationDate;
    container.querySelector('#detail-user').textContent = userName;
    container.querySelector('#detail-operation-type').textContent = history.操作種別 || '';
    container.querySelector('#detail-screen').textContent = history.操作画面 || '';
    container.querySelector('#detail-target-table').textContent = history.操作対象テーブル || '';
    container.querySelector('#detail-target-id').textContent = history.操作対象ID || '';
    container.querySelector('#detail-ip').textContent = history.IPアドレス || '';
    container.querySelector('#detail-user-agent').textContent = history.ユーザーエージェント || '';
    container.querySelector('#detail-result').textContent = history.処理結果 || '';
    container.querySelector('#detail-processing-time').textContent = history.処理時間 ? `${history.処理時間}ms` : '';
    container.querySelector('#detail-content').textContent = history.操作内容 || '';
    container.querySelector('#detail-error').textContent = history.エラーメッセージ || '';

    container.querySelector('#detail-modal').classList.remove('hidden');
  }

  // 初期データ読み込み
  async function loadInitialData() {
    await loadUsers();
    await applyFilters();
  }

  // イベントリスナー登録
  container.querySelector('#btn-search').addEventListener('click', applyFilters);
  container.querySelector('#btn-clear').addEventListener('click', clearFilters);
  container.querySelector('#btn-csv-export').addEventListener('click', exportToCsv);

  // ページネーション
  container.querySelector('#btn-prev').addEventListener('click', () => {
    if (currentPage > 1) {
      currentPage--;
      renderRows(filteredData);
    }
  });

  container.querySelector('#btn-next').addEventListener('click', () => {
    const totalPages = Math.ceil(filteredData.length / ITEMS_PER_PAGE);
    if (currentPage < totalPages) {
      currentPage++;
      renderRows(filteredData);
    }
  });

  // モーダル関連
  container.querySelector('#btn-close-modal').addEventListener('click', () => {
    container.querySelector('#detail-modal').classList.add('hidden');
  });

  container.querySelector('#detail-modal').addEventListener('click', (e) => {
    if (e.target.id === 'detail-modal') {
      container.querySelector('#detail-modal').classList.add('hidden');
    }
  });

  // 行レベル操作のイベントデリゲーション
  container.addEventListener('click', (e) => {
    const detailBtn = e.target.closest('.detail-btn');
    if (detailBtn) {
      showDetailModal(detailBtn.dataset.id);
    }
  });

  // 初期化
  loadInitialData();
}

function(container, apiUrl, tables) {
  // 今日の日付を取得
  const today = new Date().toISOString().split('T')[0];
  const tomorrow = new Date(Date.now() + 24 * 60 * 60 * 1000).toISOString().split('T')[0];
  const oneMonthAgo = new Date(Date.now() - 30 * 24 * 60 * 60 * 1000).toISOString().split('T')[0];

  // 初期値設定
  container.querySelector('#prediction-start-date').value = tomorrow;
  container.querySelector('#prediction-end-date').value = new Date(Date.now() + 7 * 24 * 60 * 60 * 1000).toISOString().split('T')[0];
  container.querySelector('#learning-start-date').value = oneMonthAgo;
  container.querySelector('#learning-end-date').value = today;

  // 店舗データの読み込み
  async function loadStores() {
    const stores = await window.aivicApi.list(1); // 店舗マスタ
    const storeSelect = container.querySelector('#store-select');
    if (stores) {
      stores.forEach(store => {
        if (store.有効フラグ) {
          const option = document.createElement('option');
          option.value = store.店舗ID;
          option.textContent = `${store.店舗名} (${store.店舗コード})`;
          storeSelect.appendChild(option);
        }
      });
    }
  }

  // 商品カテゴリの読み込み
  async function loadCategories() {
    const products = await window.aivicApi.list(2); // 商品マスタ
    const categoryContainer = container.querySelector('#category-checkboxes');
    const categories = new Set();

    if (products) {
      products.forEach(product => {
        if (product.有効フラグ && product.AI予測対象フラグ) {
          categories.add(product.商品カテゴリID);
        }
      });

      categories.forEach(categoryId => {
        const label = document.createElement('label');
        label.style.display = 'block';
        label.style.marginBottom = '5px';
        label.innerHTML = `<input type="checkbox" class="category-checkbox" value="${categoryId}"> カテゴリ ${categoryId.substring(0, 8)}...`;
        categoryContainer.appendChild(label);
      });
    }
  }

  // 全選択チェックボックスの処理
  container.querySelector('#select-all-categories').addEventListener('change', function() {
    const checkboxes = container.querySelectorAll('.category-checkbox');
    checkboxes.forEach(cb => cb.checked = this.checked);
  });

  // 季節要因スライダーの値表示更新
  container.querySelector('#seasonal-factor').addEventListener('input', function() {
    container.querySelector('#seasonal-value').textContent = this.value + '%';
  });

  // 天候データ取込ボタン
  container.querySelector('#btn-weather-import').addEventListener('click', async function() {
    this.disabled = true;
    this.textContent = '取込中...';

    try {
      // 模擬的な天候データ取込処理
      await new Promise(resolve => setTimeout(resolve, 2000));

      // 成功メッセージ
      const message = document.createElement('div');
      message.style.color = 'var(--primary)';
      message.style.fontSize = '12px';
      message.style.marginTop = '5px';
      message.textContent = '天候データの取込が完了しました';
      this.parentNode.appendChild(message);

      setTimeout(() => {
        if (message.parentNode) {
          message.parentNode.removeChild(message);
        }
      }, 3000);

    } catch (error) {
      // エラーメッセージ
      const message = document.createElement('div');
      message.style.color = '#ff6a00';
      message.style.fontSize = '12px';
      message.style.marginTop = '5px';
      message.textContent = '天候データの取得に失敗しました。データソースの設定を確認してください。';
      this.parentNode.appendChild(message);
    } finally {
      this.disabled = false;
      this.textContent = '天候データ取込';
    }
  });

  // イベントデータ取込ボタン
  container.querySelector('#btn-event-import').addEventListener('click', async function() {
    this.disabled = true;
    this.textContent = '取込中...';

    try {
      // 模擬的なイベントデータ取込処理
      await new Promise(resolve => setTimeout(resolve, 1500));

      // 成功メッセージ
      const message = document.createElement('div');
      message.style.color = 'var(--primary)';
      message.style.fontSize = '12px';
      message.style.marginTop = '5px';
      message.textContent = 'イベントデータの取込が完了しました';
      this.parentNode.appendChild(message);

      setTimeout(() => {
        if (message.parentNode) {
          message.parentNode.removeChild(message);
        }
      }, 3000);

    } catch (error) {
      // エラーメッセージ
      const message = document.createElement('div');
      message.style.color = '#ff6a00';
      message.style.fontSize = '12px';
      message.style.marginTop = '5px';
      message.textContent = 'イベントデータの取込に失敗しました。ファイル形式を確認してください。';
      this.parentNode.appendChild(message);
    } finally {
      this.disabled = false;
      this.textContent = 'イベントデータ取込';
    }
  });

  // バリデーション関数
  function validateForm() {
    const errors = [];

    // 予測期間チェック
    const startDate = container.querySelector('#prediction-start-date').value;
    const endDate = container.querySelector('#prediction-end-date').value;
    if (!startDate || !endDate) {
      errors.push('予測期間の開始日と終了日を入力してください');
    } else {
      const start = new Date(startDate);
      const end = new Date(endDate);
      const today = new Date();

      if (start < today || end < today) {
        errors.push('予測期間に過去の日付は指定できません');
      }

      const diffTime = Math.abs(end - start);
      const diffDays = Math.ceil(diffTime / (1000 * 60 * 60 * 24));
      if (diffDays > 365) {
        errors.push('予測期間は1年以内で設定してください');
      }
    }

    // 店舗選択チェック
    if (!container.querySelector('#store-select').value) {
      errors.push('店舗を選択してください');
    }

    // 商品カテゴリチェック
    const selectedCategories = container.querySelectorAll('.category-checkbox:checked');
    if (selectedCategories.length === 0) {
      errors.push('商品カテゴリを選択してください');
    }

    // 予測モデルチェック
    const selectedModel = container.querySelector('input[name="prediction-model"]:checked');
    if (!selectedModel) {
      errors.push('予測モデルを選択してください');
    }

    // 学習データ期間チェック
    const learningStart = container.querySelector('#learning-start-date').value;
    const learningEnd = container.querySelector('#learning-end-date').value;
    if (!learningStart || !learningEnd) {
      errors.push('学習データ期間の開始日と終了日を入力してください');
    } else {
      const lStart = new Date(learningStart);
      const lEnd = new Date(learningEnd);
      const pStart = new Date(startDate);

      const learningDays = Math.ceil((lEnd - lStart) / (1000 * 60 * 60 * 24));
      const predictionDays = Math.ceil((new Date(endDate) - pStart) / (1000 * 60 * 60 * 24));

      if (learningDays < predictionDays) {
        errors.push('学習データ期間は予測期間以上に設定してください');
      }
    }

    return errors;
  }

  // AI予測実行ボタン
  container.querySelector('#btn-execute-prediction').addEventListener('click', async function() {
    const errors = validateForm();
    if (errors.length > 0) {
      alert(errors.join('\n'));
      return;
    }

    // UI無効化
    this.disabled = true;
    this.textContent = '予測実行中...';
    const allInputs = container.querySelectorAll('input, select, button');
    allInputs.forEach(input => input.disabled = true);

    // 進捗バー表示
    const progressContainer = container.querySelector('#progress-container');
    const progressBar = container.querySelector('#progress-bar');
    const progressText = container.querySelector('#progress-text');
    const resultContainer = container.querySelector('#result-container');

    progressContainer.classList.remove('hidden');
    resultContainer.classList.add('hidden');

    try {
      // 模擬的な予測処理（段階的に進捗更新）
      const steps = [
        { progress: 10, text: 'データ収集中...' },
        { progress: 30, text: '前処理実行中...' },
        { progress: 50, text: 'モデル学習中...' },
        { progress: 70, text: '予測計算中...' },
        { progress: 90, text: '結果生成中...' },
        { progress: 100, text: '完了' }
      ];

      for (const step of steps) {
        await new Promise(resolve => setTimeout(resolve, 1000));
        progressBar.style.width = step.progress + '%';
        progressText.textContent = step.text;
      }

      // 予測結果の生成と保存
      const selectedCategories = Array.from(container.querySelectorAll('.category-checkbox:checked')).map(cb => cb.value);
      const storeId = container.querySelector('#store-select').value;
      const startDate = container.querySelector('#prediction-start-date').value;
      const endDate = container.querySelector('#prediction-end-date').value;
      const model = container.querySelector('input[name="prediction-model"]:checked').value;
      const accuracyThreshold = parseFloat(container.querySelector('#accuracy-threshold').value);

      // 模擬予測結果データ
      const results = [];
      const stores = await window.aivicApi.list(1);
      const products = await window.aivicApi.list(2);
      const selectedStore = stores?.find(s => s.店舗ID === storeId);

      if (selectedStore && products) {
        const targetProducts = products.filter(p => 
          selectedCategories.includes(p.商品カテゴリID) && 
          p.有効フラグ && 
          p.AI予測対象フラグ
        );

        for (const product of targetProducts.slice(0, 10)) { // 最大10件まで表示
          const accuracy = Math.random() * (1 - accuracyThreshold) + accuracyThreshold;
          const predictedQty = Math.floor(Math.random() * 100) + 10;
          const recommendedQty = Math.floor(predictedQty * 1.1);

          const result = {
            店舗ID: storeId,
            商品ID: product.商品ID,
            予測対象日: startDate,
            予測数量: predictedQty,
            予測精度: accuracy,
            推奨発注数量: recommendedQty,
            予測モデルバージョン: model + '_v1.0',
            予測ステータス: '完了',
            発注済フラグ: false,
            作成日時: new Date().toISOString(),
            更新日時: new Date().toISOString()
          };

          // 需要予測結果テーブルに保存
          await window.aivicApi.save(9, result);

          results.push({
            店舗名: selectedStore.店舗名,
            商品名: product.商品名,
            予測日: startDate,
            予測数量: predictedQty,
            予測精度: (accuracy * 100).toFixed(1) + '%',
            推奨発注数量: recommendedQty
          });
        }
      }

      // 結果表示
      const resultTbody = container.querySelector('#result-tbody');
      resultTbody.innerHTML = results.map(r => `
        <tr>
          <td>${r.店舗名}</td>
          <td>${r.商品名}</td>
          <td>${r.予測日}</td>
          <td>${r.予測数量}</td>
          <td>${r.予測精度}</td>
          <td>${r.推奨発注数量}</td>
        </tr>
      `).join('');

      resultContainer.classList.remove('hidden');

    } catch (error) {
      alert('AI予測実行が失敗しました。システム管理者にお問い合わせください。');
    } finally {
      // UI復元
      allInputs.forEach(input => input.disabled = false);
      this.disabled = false;
      this.textContent = 'AI予測実行';
      progressContainer.classList.add('hidden');
    }
  });

  // 初期データ読み込み
  loadStores();
  loadCategories();
}

function(container, apiUrl, tables) {
  let selectedProduct = null;
  let currentPrediction = null;

  // 店舗データを読み込み
  function loadStores() {
    const storeSelect = container.querySelector('#store-select');
    const storeTable = tables.find(t => t.tableName === '店舗マスタ');
    if (storeTable && storeTable.records) {
      storeTable.records.forEach(store => {
        if (store.有効フラグ) {
          const option = document.createElement('option');
          option.value = store.店舗ID;
          option.textContent = `${store.店舗コード} - ${store.店舗名}`;
          storeSelect.appendChild(option);
        }
      });
    }
  }

  // 商品データを読み込み
  function loadProducts(storeId = '', categoryId = '', searchTerm = '') {
    const tbody = container.querySelector('#product-tbody');
    const productTable = tables.find(t => t.tableName === '商品マスタ');

    if (!productTable || !productTable.records) {
      tbody.innerHTML = '<tr><td colspan="7" class="muted">商品データがありません</td></tr>';
      return;
    }

    let filteredProducts = productTable.records.filter(product => product.有効フラグ);

    if (searchTerm) {
      filteredProducts = filteredProducts.filter(product => 
        product.商品名.toLowerCase().includes(searchTerm.toLowerCase()) ||
        product.商品コード.toLowerCase().includes(searchTerm.toLowerCase())
      );
    }

    tbody.innerHTML = filteredProducts.map(product => `
      <tr class="product-row" data-id="${product.商品ID}">
        <td><input type="radio" name="product-select" value="${product.商品ID}"></td>
        <td>${product.商品コード || ''}</td>
        <td>${product.商品名 || ''}</td>
        <td>カテゴリ${Math.floor(Math.random() * 5) + 1}</td>
        <td>¥${product.単価 || 0}</td>
        <td>¥${product.販売価格 || 0}</td>
        <td>${product.リードタイム日数 || 0}日</td>
      </tr>
    `).join('');
  }

  // バリデーション関数
  function validateForm() {
    let isValid = true;

    // 店舗選択チェック
    const storeSelect = container.querySelector('#store-select');
    const storeError = container.querySelector('#store-error');
    if (!storeSelect.value) {
      storeError.classList.remove('hidden');
      isValid = false;
    } else {
      storeError.classList.add('hidden');
    }

    // 商品選択チェック
    const productSelected = container.querySelector('input[name="product-select"]:checked');
    const productError = container.querySelector('#product-error');
    if (!productSelected) {
      productError.classList.remove('hidden');
      isValid = false;
    } else {
      productError.classList.add('hidden');
    }

    // 期間チェック
    const periodStart = container.querySelector('#period-start');
    const periodEnd = container.querySelector('#period-end');
    const periodStartError = container.querySelector('#period-start-error');
    const periodEndError = container.querySelector('#period-end-error');

    if (!periodStart.value) {
      periodStartError.classList.remove('hidden');
      isValid = false;
    } else {
      periodStartError.classList.add('hidden');
    }

    if (!periodEnd.value) {
      periodEndError.classList.remove('hidden');
      isValid = false;
    } else {
      periodEndError.classList.add('hidden');
    }

    // 在庫数チェック
    const currentStock = container.querySelector('#current-stock');
    const stockError = container.querySelector('#stock-error');
    if (currentStock.value < 0 || isNaN(currentStock.value)) {
      stockError.classList.remove('hidden');
      isValid = false;
    } else {
      stockError.classList.add('hidden');
    }

    // 安全在庫チェック
    const safetyStock = container.querySelector('#safety-stock');
    const safetyError = container.querySelector('#safety-error');
    if (isNaN(safetyStock.value) || safetyStock.value === '') {
      safetyError.classList.remove('hidden');
      isValid = false;
    } else {
      safetyError.classList.add('hidden');
    }

    // リードタイムチェック
    const leadTime = container.querySelector('#lead-time');
    const leadTimeError = container.querySelector('#leadtime-error');
    if (leadTime.value < 1 || leadTime.value > 365 || isNaN(leadTime.value)) {
      leadTimeError.classList.remove('hidden');
      isValid = false;
    } else {
      leadTimeError.classList.add('hidden');
    }

    // 季節補正係数チェック
    const seasonalFactor = container.querySelector('#seasonal-factor');
    const seasonalError = container.querySelector('#seasonal-error');
    if (seasonalFactor.value < 0.01 || seasonalFactor.value > 9.99 || isNaN(seasonalFactor.value)) {
      seasonalError.classList.remove('hidden');
      isValid = false;
    } else {
      seasonalError.classList.add('hidden');
    }

    // 手動調整発注量チェック
    const manualQty = container.querySelector('#manual-order-qty');
    const manualError = container.querySelector('#manual-error');
    if (manualQty.value && (manualQty.value < 0 || isNaN(manualQty.value))) {
      manualError.classList.remove('hidden');
      isValid = false;
    } else {
      manualError.classList.add('hidden');
    }

    return isValid;
  }

  // 発注量計算
  function calculateOrderQuantity() {
    if (!validateForm()) return;

    const currentStock = parseInt(container.querySelector('#current-stock').value) || 0;
    const safetyStock = parseInt(container.querySelector('#safety-stock').value) || 0;
    const leadTime = parseInt(container.querySelector('#lead-time').value) || 1;
    const weatherImpact = parseInt(container.querySelector('#weather-impact').value) || 100;
    const eventImpact = parseInt(container.querySelector('#event-impact').value) || 100;
    const seasonalFactor = parseFloat(container.querySelector('#seasonal-factor').value) || 1.0;

    // 基本需要量（サンプル計算）
    const baseDemand = 100; // 実際はAI予測値を使用

    // 影響度調整
    const adjustedDemand = baseDemand * (weatherImpact / 100) * (eventImpact / 100) * seasonalFactor;

    // リードタイム期間の需要
    const leadTimeDemand = adjustedDemand * (leadTime / 7); // 週単位で計算

    // AI推奨発注量
    const aiRecommended = Math.max(0, Math.ceil(leadTimeDemand + safetyStock - currentStock));

    // 結果表示
    container.querySelector('#ai-recommended-qty').textContent = aiRecommended;

    // 手動調整値がある場合はそれを、なければAI推奨値を最終値とする
    const manualQty = container.querySelector('#manual-order-qty').value;
    const finalQty = manualQty ? parseInt(manualQty) : aiRecommended;
    container.querySelector('#final-order-qty').textContent = finalQty;

    // 予測結果も更新
    container.querySelector('#predicted-demand').textContent = Math.ceil(adjustedDemand);
    container.querySelector('#prediction-accuracy').textContent = '85%';
    container.querySelector('#recommended-order').textContent = aiRecommended;
  }

  // AI予測実行
  function executeAIPrediction() {
    const storeSelect = container.querySelector('#store-select');
    const periodStart = container.querySelector('#period-start');
    const periodEnd = container.querySelector('#period-end');

    if (!storeSelect.value || !periodStart.value || !periodEnd.value) {
      if (!periodStart.value || !periodEnd.value) {
        container.querySelector('#period-start-error').classList.remove('hidden');
        container.querySelector('#period-end-error').classList.remove('hidden');
      }
      return;
    }

    // サンプル予測結果を表示
    container.querySelector('#predicted-demand').textContent = '120';
    container.querySelector('#prediction-accuracy').textContent = '87%';
    container.querySelector('#recommended-order').textContent = '85';
  }

  // 初期化
  loadStores();
  loadProducts();

  // スライダーの値表示更新
  container.querySelector('#weather-impact').addEventListener('input', (e) => {
    container.querySelector('#weather-value').textContent = e.target.value + '%';
  });

  container.querySelector('#event-impact').addEventListener('input', (e) => {
    container.querySelector('#event-value').textContent = e.target.value + '%';
  });

  // 商品検索
  container.querySelector('#btn-product-search').addEventListener('click', () => {
    const searchTerm = container.querySelector('#product-search').value;
    loadProducts('', '', searchTerm);
  });

  // 絞り込み実行
  container.querySelector('#btn-filter').addEventListener('click', () => {
    const storeId = container.querySelector('#store-select').value;
    const categoryId = container.querySelector('#category-select').value;
    const searchTerm = container.querySelector('#product-search').value;
    loadProducts(storeId, categoryId, searchTerm);
  });

  // AI予測実行
  container.querySelector('#btn-ai-predict').addEventListener('click', executeAIPrediction);

  // 計算実行
  container.querySelector('#btn-calculate').addEventListener('click', calculateOrderQuantity);

  // 商品選択時の処理
  container.addEventListener('change', (e) => {
    if (e.target.name === 'product-select') {
      selectedProduct = e.target.value;
      container.querySelector('#product-error').classList.add('hidden');

      // 選択行のハイライト
      container.querySelectorAll('.product-row').forEach(row => {
        row.classList.remove('selected');
      });
      e.target.closest('tr').classList.add('selected');
    }
  });

  // 手動調整値変更時の最終発注量更新
  container.querySelector('#manual-order-qty').addEventListener('input', (e) => {
    const manualQty = parseInt(e.target.value);
    const aiQty = parseInt(container.querySelector('#ai-recommended-qty').textContent) || 0;

    if (manualQty >= 0) {
      container.querySelector('#final-order-qty').textContent = manualQty || aiQty;
      container.querySelector('#manual-error').classList.add('hidden');
    }
  });
}

function(container, apiUrl, tables) {
  // テーブルインデックス定義
  const STORE_TABLE = 1;  // 店舗マスタ
  const PRODUCT_TABLE = 2; // 商品マスタ
  const ORDER_TABLE = 7;   // 発注データ

  let currentOrders = [];
  let stores = [];
  let products = [];

  // 現在日時を表示
  function updateOrderDate() {
    const now = new Date();
    const dateStr = now.getFullYear() + '年' + 
                   String(now.getMonth() + 1).padStart(2, '0') + '月' + 
                   String(now.getDate()).padStart(2, '0') + '日';
    container.querySelector('#order-date').textContent = dateStr;
  }

  // 発注データテーブル再描画
  function renderOrderRows(orders) {
    const tbody = container.querySelector('#order-tbody');

    if (!orders || orders.length === 0) {
      tbody.innerHTML = `
        <tr>
          <td colspan="8" style="text-align: center; padding: 2rem; color: var(--text-muted);">
            発注対象のデータがありません
          </td>
        </tr>
      `;
      return;
    }

    tbody.innerHTML = orders.map(order => {
      const product = products.find(p => p.商品ID === order.商品ID) || {};
      const statusBadge = getStatusBadge(order.発注ステータス);
      const amount = (order.発注数量 || 0) * (order.発注単価 || 0);

      return `
        <tr data-id="${order.発注ID}">
          <td style="text-align: center;">
            <input type="checkbox" class="order-checkbox" data-id="${order.発注ID}" 
                   ${order.発注ステータス === '送信済' ? 'disabled' : ''}>
          </td>
          <td>${product.商品コード || ''}</td>
          <td>${product.商品名 || ''}</td>
          <td style="text-align: right;">${order.予測数量 || 0}</td>
          <td style="text-align: right;">${order.発注数量 || 0}</td>
          <td>${order.仕入先名 || ''}</td>
          <td style="text-align: right;">¥${amount.toLocaleString()}</td>
          <td>${statusBadge}</td>
        </tr>
      `;
    }).join('');

    updateTotalAmount();
  }

  // ステータスバッジ生成
  function getStatusBadge(status) {
    const badges = {
      '発注済': '<span style="background: #ffa500; color: white; padding: 0.25rem 0.5rem; border-radius: 12px; font-size: 0.8rem;">発注済</span>',
      '送信済': '<span style="background: #44aa44; color: white; padding: 0.25rem 0.5rem; border-radius: 12px; font-size: 0.8rem;">送信済</span>',
      '送信待ち': '<span style="background: #ff6a00; color: white; padding: 0.25rem 0.5rem; border-radius: 12px; font-size: 0.8rem;">送信待ち</span>',
      'キャンセル': '<span style="background: #888; color: white; padding: 0.25rem 0.5rem; border-radius: 12px; font-size: 0.8rem;">キャンセル</span>'
    };
    return badges[status] || `<span style="background: var(--text-muted); color: white; padding: 0.25rem 0.5rem; border-radius: 12px; font-size: 0.8rem;">${status}</span>`;
  }

  // 合計金額更新
  function updateTotalAmount() {
    const checkboxes = container.querySelectorAll('.order-checkbox:checked:not(:disabled)');
    let total = 0;
    let count = 0;

    checkboxes.forEach(cb => {
      const orderId = cb.dataset.id;
      const order = currentOrders.find(o => o.発注ID === orderId);
      if (order) {
        total += (order.発注数量 || 0) * (order.発注単価 || 0);
        count++;
      }
    });

    container.querySelector('#total-amount').textContent = `¥${total.toLocaleString()}`;
    container.querySelector('#selected-count').textContent = count;

    // 送信ボタンの有効/無効制御
    const sendBtn = container.querySelector('#btn-send');
    sendBtn.disabled = count === 0;
  }

  // 店舗選択肢を読み込み
  async function loadStores() {
    const storeData = await window.aivicApi.list(STORE_TABLE);
    if (storeData) {
      stores = storeData.filter(s => s.有効フラグ);
      const select = container.querySelector('#store-select');
      select.innerHTML = '<option value="">店舗を選択してください</option>' +
        stores.map(store => 
          `<option value="${store.店舗ID}">${store.店舗名} (${store.店舗コード})</option>`
        ).join('');
    }
  }

  // 商品マスタを読み込み
  async function loadProducts() {
    const productData = await window.aivicApi.list(PRODUCT_TABLE);
    if (productData) {
      products = productData;
    }
  }

  // 店舗別発注データを読み込み
  async function loadOrdersByStore(storeId) {
    if (!storeId) {
      currentOrders = [];
      renderOrderRows([]);
      return;
    }

    const orderData = await window.aivicApi.list(ORDER_TABLE);
    if (orderData) {
      // 選択店舗の発注データのみフィルタ（送信待ち・発注済のみ）
      currentOrders = orderData.filter(order => 
        order.店舗ID === storeId && 
        ['発注済', '送信待ち'].includes(order.発注ステータス)
      );
      renderOrderRows(currentOrders);
    }
  }

  // エラーメッセージ表示
  function showError(message) {
    const errorDiv = container.querySelector('#error-message');
    errorDiv.textContent = message;
    errorDiv.classList.remove('hidden');
    setTimeout(() => errorDiv.classList.add('hidden'), 5000);
  }

  // 成功メッセージ表示
  function showSuccess(message) {
    const successDiv = container.querySelector('#success-message');
    successDiv.textContent = message;
    successDiv.classList.remove('hidden');
    setTimeout(() => successDiv.classList.add('hidden'), 3000);
  }

  // 発注送信処理
  async function sendOrders() {
    const checkboxes = container.querySelectorAll('.order-checkbox:checked:not(:disabled)');

    if (checkboxes.length === 0) {
      showError('発注する商品を選択してください');
      return;
    }

    const orderIds = Array.from(checkboxes).map(cb => cb.dataset.id);
    const ordersToSend = currentOrders.filter(o => orderIds.includes(o.発注ID));

    // 送信済みデータの重複チェック
    const alreadySent = ordersToSend.filter(o => o.発注ステータス === '送信済');
    if (alreadySent.length > 0) {
      showError('この発注データは既に送信済みです。重複送信はできません。');
      return;
    }

    try {
      // 各発注データのステータスを「送信済」に更新
      let successCount = 0;
      for (const order of ordersToSend) {
        const updated = await window.aivicApi.update(ORDER_TABLE, order.発注ID, {
          発注ステータス: '送信済',
          更新日時: new Date().toISOString(),
          更新者ID: 'current-user-id' // 実際の実装では現在のユーザーIDを使用
        });

        if (updated) {
          successCount++;
        }
      }

      if (successCount > 0) {
        showSuccess(`${successCount}件の発注データを正常に送信しました`);
        // データを再読み込み
        const storeId = container.querySelector('#store-select').value;
        await loadOrdersByStore(storeId);
        // 全選択チェックボックスをリセット
        container.querySelector('#select-all').checked = false;
      } else {
        showError('発注送信に失敗しました');
      }
    } catch (error) {
      showError('ネットワークエラーが発生しました。接続を確認してください。');
    }
  }

  // 初期化処理
  async function initialize() {
    updateOrderDate();
    await loadStores();
    await loadProducts();

    // 初期データがある場合は表示
    if (tables[ORDER_TABLE] && tables[ORDER_TABLE].records) {
      currentOrders = tables[ORDER_TABLE].records.filter(order => 
        ['発注済', '送信待ち'].includes(order.発注ステータス)
      );
    }
  }

  // イベントリスナー設定

  // 店舗選択変更
  container.querySelector('#store-select').addEventListener('change', async (e) => {
    const storeId = e.target.value;
    if (!storeId) {
      showError('指定された店舗が存在しません');
      return;
    }
    await loadOrdersByStore(storeId);
  });

  // 全選択チェックボックス
  container.querySelector('#select-all').addEventListener('change', (e) => {
    const checkboxes = container.querySelectorAll('.order-checkbox:not(:disabled)');
    checkboxes.forEach(cb => cb.checked = e.target.checked);
    updateTotalAmount();
  });

  // 個別チェックボックス（イベントデリゲーション）
  container.addEventListener('change', (e) => {
    if (e.target.classList.contains('order-checkbox')) {
      updateTotalAmount();

      // 全選択チェックボックスの状態更新
      const allCheckboxes = container.querySelectorAll('.order-checkbox:not(:disabled)');
      const checkedCheckboxes = container.querySelectorAll('.order-checkbox:checked:not(:disabled)');
      const selectAllCb = container.querySelector('#select-all');

      if (checkedCheckboxes.length === 0) {
        selectAllCb.indeterminate = false;
        selectAllCb.checked = false;
      } else if (checkedCheckboxes.length === allCheckboxes.length) {
        selectAllCb.indeterminate = false;
        selectAllCb.checked = true;
      } else {
        selectAllCb.indeterminate = true;
      }
    }
  });

  // 送信ボタン
  container.querySelector('#btn-send').addEventListener('click', () => {
    const checkboxes = container.querySelectorAll('.order-checkbox:checked:not(:disabled)');
    const count = checkboxes.length;

    if (count === 0) {
      showError('発注する商品を選択してください');
      return;
    }

    // 合計金額計算
    let total = 0;
    checkboxes.forEach(cb => {
      const orderId = cb.dataset.id;
      const order = currentOrders.find(o => o.発注ID === orderId);
      if (order) {
        total += (order.発注数量 || 0) * (order.発注単価 || 0);
      }
    });

    // 確認モーダル表示
    container.querySelector('#confirm-count').textContent = count;
    container.querySelector('#confirm-amount').textContent = `¥${total.toLocaleString()}`;
    container.querySelector('#send-modal').style.display = 'block';
  });

  // モーダル操作
  container.querySelector('#btn-cancel').addEventListener('click', () => {
    container.querySelector('#send-modal').style.display = 'none';
  });

  container.querySelector('#btn-confirm').addEventListener('click', async () => {
    container.querySelector('#send-modal').style.display = 'none';
    await sendOrders();
  });

  // モーダル背景クリックで閉じる
  container.querySelector('#send-modal').addEventListener('click', (e) => {
    if (e.target.id === 'send-modal') {
      container.querySelector('#send-modal').style.display = 'none';
    }
  });

  // 初期化実行
  initialize();
}

function(container, apiUrl, tables) {
  // テーブルインデックス定義
  const STORES_TABLE = 1;
  const PRODUCTS_TABLE = 2;
  const FORECAST_TABLE = 8;
  const ORDER_TABLE = 9;

  let calculationResults = [];

  // 店舗データを読み込んでセレクトボックスに設定
  function loadStores() {
    window.aivicApi.list(STORES_TABLE).then(stores => {
      if (!stores) return;
      const storeSelect = container.querySelector('#store-select');
      storeSelect.innerHTML = '<option value="">店舗を選択してください</option>';
      stores.filter(store => store.有効フラグ).forEach(store => {
        storeSelect.innerHTML += `<option value="${store.店舗ID}">${store.店舗名}</option>`;
      });
    });
  }

  // エラーメッセージ表示
  function showError(message) {
    const errorDiv = container.querySelector('#error-message');
    errorDiv.textContent = message;
    errorDiv.classList.remove('hidden');
    setTimeout(() => {
      errorDiv.classList.add('hidden');
    }, 5000);
  }

  // バリデーション
  function validateInputs() {
    const storeId = container.querySelector('#store-select').value;
    const category = container.querySelector('#category-select').value;
    const periodStart = container.querySelector('#period-start').value;
    const periodEnd = container.querySelector('#period-end').value;
    const safetyStock = parseInt(container.querySelector('#safety-stock').value) || 0;
    const leadTime = parseInt(container.querySelector('#lead-time').value) || 0;
    const orderPoint = parseInt(container.querySelector('#order-point').value) || 0;

    if (!storeId) {
      showError('店舗を選択してください');
      return false;
    }

    if (!category) {
      showError('商品カテゴリを選択してください');
      return false;
    }

    if (!periodStart || !periodEnd) {
      showError('計算対象期間を設定してください');
      return false;
    }

    if (new Date(periodStart) >= new Date(periodEnd)) {
      showError('期間の開始日は終了日より前に設定してください');
      return false;
    }

    if (safetyStock < 0) {
      showError('安全在庫数は0以上の値を入力してください');
      return false;
    }

    if (leadTime <= 0) {
      showError('リードタイムは1以上の値を入力してください');
      return false;
    }

    if (orderPoint < 0) {
      showError('発注点は0以上の値を入力してください');
      return false;
    }

    return true;
  }

  // 需要予測データ取得
  async function getForecastData(storeId, category, periodStart, periodEnd) {
    try {
      const forecasts = await window.aivicApi.list(FORECAST_TABLE);
      if (!forecasts) {
        showError('需要予測データの取得に失敗しました');
        return null;
      }

      const products = await window.aivicApi.list(PRODUCTS_TABLE);
      if (!products) {
        showError('商品データの取得に失敗しました');
        return null;
      }

      // カテゴリに該当する商品を取得
      const categoryProducts = products.filter(p => 
        p.商品カテゴリID && p.商品カテゴリID.includes(category) && p.有効フラグ
      );

      if (categoryProducts.length === 0) {
        showError('選択されたカテゴリに該当する商品が見つかりません');
        return null;
      }

      // 予測データをフィルタリング
      const startDate = new Date(periodStart);
      const endDate = new Date(periodEnd);

      const filteredForecasts = forecasts.filter(f => {
        const forecastDate = new Date(f.予測対象日);
        return f.店舗ID === storeId && 
               forecastDate >= startDate && 
               forecastDate <= endDate &&
               categoryProducts.some(p => p.商品ID === f.商品ID);
      });

      return { forecasts: filteredForecasts, products: categoryProducts };
    } catch (error) {
      showError('需要予測データの取得に失敗しました');
      return null;
    }
  }

  // 在庫データ取得（模擬）
  function getInventoryData(productId) {
    // 実際の実装では在庫管理システムから取得
    return {
      currentStock: Math.floor(Math.random() * 500) + 50,
      reservedStock: Math.floor(Math.random() * 50)
    };
  }

  // 発注量計算
  function calculateOrderQuantity(forecastQuantity, currentStock, safetyStock, leadTime, avgDailyDemand) {
    const leadTimeDemand = avgDailyDemand * leadTime;
    const totalRequired = leadTimeDemand + safetyStock;
    const orderQuantity = Math.max(0, totalRequired - currentStock);

    return {
      orderQuantity: Math.ceil(orderQuantity),
      leadTimeDemand,
      totalRequired,
      orderTiming: currentStock <= (leadTimeDemand + safetyStock) ? '即時' : '通常'
    };
  }

  // 計算結果表示
  function displayResults(results) {
    // 需要予測結果表示
    const forecastSection = container.querySelector('#forecast-result');
    const totalForecast = results.reduce((sum, r) => sum + r.forecastQuantity, 0);
    const avgForecast = results.length > 0 ? Math.round(totalForecast / results.length) : 0;

    container.querySelector('#forecast-period').textContent = 
      `${container.querySelector('#period-start').value} ～ ${container.querySelector('#period-end').value}`;
    container.querySelector('#total-forecast').textContent = `${totalForecast}個`;
    container.querySelector('#avg-forecast').textContent = `${avgForecast}個/日`;
    forecastSection.classList.remove('hidden');

    // 在庫状況表示
    const inventorySection = container.querySelector('#inventory-status');
    const avgCurrentStock = results.length > 0 ? Math.round(results.reduce((sum, r) => sum + r.currentStock, 0) / results.length) : 0;

    container.querySelector('#current-stock').textContent = `${avgCurrentStock}個`;
    container.querySelector('#safety-stock-display').textContent = `${container.querySelector('#safety-stock').value || 0}個`;
    container.querySelector('#order-point-display').textContent = `${container.querySelector('#order-point').value || 0}個`;
    inventorySection.classList.remove('hidden');

    // 結果テーブル表示
    renderResultTable(results);
    container.querySelector('#result-table-section').classList.remove('hidden');
  }

  // 結果テーブル描画
  function renderResultTable(results) {
    const tbody = container.querySelector('#result-tbody');
    tbody.innerHTML = results.map(result => `
      <tr data-product-id="${result.productId}">
        <td><a href="#" class="product-link" data-product-id="${result.productId}">${result.productName}</a></td>
        <td>${result.productCode}</td>
        <td>${result.forecastQuantity}個</td>
        <td>${result.currentStock}個</td>
        <td>${result.safetyStock}個</td>
        <td><strong>${result.orderQuantity}個</strong></td>
        <td><span class="status-badge ${result.orderTiming === '即時' ? 'status-critical' : 'status-normal'}">${result.orderTiming}</span></td>
        <td>
          <button class="action-btn secondary detail-btn" data-product-id="${result.productId}">詳細</button>
        </td>
      </tr>
    `).join('');
  }

  // 計算実行
  async function executeCalculation() {
    if (!validateInputs()) return;

    const storeId = container.querySelector('#store-select').value;
    const category = container.querySelector('#category-select').value;
    const periodStart = container.querySelector('#period-start').value;
    const periodEnd = container.querySelector('#period-end').value;
    const safetyStock = parseInt(container.querySelector('#safety-stock').value) || 0;
    const leadTime = parseInt(container.querySelector('#lead-time').value) || 1;

    // 計算ボタンを無効化
    const calcBtn = container.querySelector('#btn-calculate');
    calcBtn.disabled = true;
    calcBtn.textContent = '計算中...';

    try {
      const forecastData = await getForecastData(storeId, category, periodStart, periodEnd);
      if (!forecastData) {
        calcBtn.disabled = false;
        calcBtn.textContent = '計算実行';
        return;
      }

      const { forecasts, products } = forecastData;

      // 商品ごとに計算
      const results = [];
      const productMap = new Map();

      // 商品ごとに予測データを集約
      forecasts.forEach(f => {
        if (!productMap.has(f.商品ID)) {
          productMap.set(f.商品ID, []);
        }
        productMap.get(f.商品ID).push(f);
      });

      for (const [productId, productForecasts] of productMap) {
        const product = products.find(p => p.商品ID === productId);
        if (!product) continue;

        const totalForecast = productForecasts.reduce((sum, f) => sum + (f.予測数量 || 0), 0);
        const avgDailyDemand = totalForecast / productForecasts.length;
        const inventory = getInventoryData(productId);

        const calculation = calculateOrderQuantity(
          totalForecast,
          inventory.currentStock,
          safetyStock,
          leadTime,
          avgDailyDemand
        );

        results.push({
          productId: product.商品ID,
          productName: product.商品名,
          productCode: product.商品コード,
          forecastQuantity: totalForecast,
          currentStock: inventory.currentStock,
          safetyStock: safetyStock,
          orderQuantity: calculation.orderQuantity,
          orderTiming: calculation.orderTiming,
          avgDailyDemand: Math.round(avgDailyDemand)
        });
      }

      calculationResults = results;
      displayResults(results);

    } catch (error) {
      showError('計算処理中にエラーが発生しました');
    } finally {
      calcBtn.disabled = false;
      calcBtn.textContent = '計算実行';
    }
  }

  // CSVエクスポート
  function exportCSV() {
    if (calculationResults.length === 0) {
      showError('エクスポートするデータがありません');
      return;
    }

    const headers = ['商品名', '商品コード', '予測需要量', '現在在庫', '安全在庫', '推奨発注量', '発注タイミング'];
    const csvContent = '\uFEFF' + [
      headers.join(','),
      ...calculationResults.map(row => [
        `"${row.productName}"`,
        `"${row.productCode}"`,
        row.forecastQuantity,
        row.currentStock,
        row.safetyStock,
        row.orderQuantity,
        `"${row.orderTiming}"`
      ].join(','))
    ].join('\n');

    const blob = new Blob([csvContent], { type: 'text/csv;charset=utf-8;' });
    const link = document.createElement('a');
    link.href = URL.createObjectURL(blob);
    link.download = `発注量計算結果_${new Date().toISOString().split('T')[0]}.csv`;
    link.click();
  }

  // 発注データ生成
  async function createOrderData() {
    if (calculationResults.length === 0) {
      showError('発注データを生成するための計算結果がありません');
      return;
    }

    const ordersToCreate = calculationResults.filter(r => r.orderQuantity > 0);
    if (ordersToCreate.length === 0) {
      showError('発注が必要な商品がありません');
      return;
    }

    try {
      const storeId = container.querySelector('#store-select').value;
      let successCount = 0;

      for (const result of ordersToCreate) {
        const orderData = {
          店舗ID: storeId,
          商品ID: result.productId,
          発注日: new Date().toISOString(),
          納期予定日: new Date(Date.now() + 7 * 24 * 60 * 60 * 1000).toISOString(), // 7日後
          発注数量: result.orderQuantity,
          予測数量: result.forecastQuantity,
          発注単価: 100, // 仮の単価
          発注金額: result.orderQuantity * 100,
          発注方法: 'AI自動発注',
          発注ステータス: '発注済',
          仕入先ID: 'supplier-001',
          発注理由: 'AI需要予測による自動発注',
          自動発注フラグ: true,
          作成者ID: 'system',
          更新者ID: 'system'
        };

        const saved = await window.aivicApi.save(ORDER_TABLE, orderData);
        if (saved) successCount++;
      }

      if (successCount > 0) {
        alert(`${successCount}件の発注データを生成しました`);
        // 発注書作成画面に遷移
        window.showScreen('scr-1778591907544');
      } else {
        showError('発注データの生成に失敗しました');
      }
    } catch (error) {
      showError('発注データ生成中にエラーが発生しました');
    }
  }

  // フォームクリア
  function clearForm() {
    container.querySelector('#store-select').value = '';
    container.querySelector('#category-select').value = '';
    container.querySelector('#period-start').value = '';
    container.querySelector('#period-end').value = '';
    container.querySelector('#safety-stock').value = '';
    container.querySelector('#lead-time').value = '';
    container.querySelector('#order-point').value = '';

    // 結果セクションを非表示
    container.querySelector('#forecast-result').classList.add('hidden');
    container.querySelector('#inventory-status').classList.add('hidden');
    container.querySelector('#result-table-section').classList.add('hidden');
    container.querySelector('#error-message').classList.add('hidden');

    calculationResults = [];
  }

  // イベントリスナー設定
  container.querySelector('#btn-calculate').addEventListener('click', executeCalculation);
  container.querySelector('#btn-clear').addEventListener('click', clearForm);
  container.querySelector('#btn-export-csv').addEventListener('click', exportCSV);
  container.querySelector('#btn-create-order').addEventListener('click', createOrderData);

  // 商品詳細リンククリック
  container.addEventListener('click', (e) => {
    const productLink = e.target.closest('.product-link');
    if (productLink) {
      e.preventDefault();
      // 商品詳細画面への遷移（実装されている場合）
      const productId = productLink.dataset.productId;
      console.log('商品詳細表示:', productId);
      return;
    }

    const detailBtn = e.target.closest('.detail-btn');
    if (detailBtn) {
      const productId = detailBtn.dataset.productId;
      const result = calculationResults.find(r => r.productId === productId);
      if (result) {
        alert(`商品詳細\n商品名: ${result.productName}\n予測需要: ${result.forecastQuantity}個\n推奨発注量: ${result.orderQuantity}個\n平均日次需要: ${result.avgDailyDemand}個`);
      }
    }
  });

  // 初期化
  loadStores();

  // デフォルト値設定
  const today = new Date();
  const nextWeek = new Date(today.getTime() + 7 * 24 * 60 * 60 * 1000);
  container.querySelector('#period-start').value = today.toISOString().split('T')[0];
  container.querySelector('#period-end').value = nextWeek.toISOString().split('T')[0];
  container.querySelector('#lead-time').value = '7';
}

function(container, apiUrl, tables) {
  const tbody = container.querySelector('#inventory-tbody');
  const storeSelect = container.querySelector('#store-select');
  const categoryFilter = container.querySelector('#category-filter');
  const productNameSearch = container.querySelector('#product-name-search');
  const productCodeSearch = container.querySelector('#product-code-search');
  const stockStatusFilter = container.querySelector('#stock-status-filter');
  const errorMessage = container.querySelector('#error-message');
  const errorText = container.querySelector('#error-text');
  const noResults = container.querySelector('#no-results');

  let allInventoryData = [];
  let storeData = [];
  let productData = [];

  // エラー表示関数
  function showError(message) {
    errorText.textContent = message;
    errorMessage.classList.remove('hidden');
    setTimeout(() => {
      errorMessage.classList.add('hidden');
    }, 5000);
  }

  // エラー非表示関数
  function hideError() {
    errorMessage.classList.add('hidden');
  }

  // 在庫状況を判定する関数
  function getStockStatus(currentStock, safetyStock) {
    if (currentStock === 0) return '不足';
    if (currentStock <= safetyStock) return '不足';
    if (currentStock > safetyStock * 2) return '過剰';
    return '適正';
  }

  // 在庫状況のスタイルを取得する関数
  function getStatusStyle(status) {
    switch (status) {
      case '不足':
        return 'background: rgba(255, 106, 0, 0.1); color: #ff6a00; padding: 4px 8px; border-radius: 4px; font-size: 12px; font-weight: 500;';
      case '過剰':
        return 'background: rgba(255, 193, 7, 0.1); color: #ffc107; padding: 4px 8px; border-radius: 4px; font-size: 12px; font-weight: 500;';
      case '適正':
        return 'background: rgba(40, 167, 69, 0.1); color: #28a745; padding: 4px 8px; border-radius: 4px; font-size: 12px; font-weight: 500;';
      default:
        return 'padding: 4px 8px; border-radius: 4px; font-size: 12px; font-weight: 500;';
    }
  }

  // バリデーション関数
  function validateInputs() {
    hideError();

    const storeId = storeSelect.value;
    if (!storeId) {
      showError('店舗を選択してください');
      return false;
    }

    const productCode = productCodeSearch.value.trim();
    if (productCode && !/^[A-Za-z0-9]+$/.test(productCode)) {
      showError('商品コードは英数字で入力してください');
      return false;
    }

    const productName = productNameSearch.value.trim();
    if (productName && /<script|javascript:|on\w+=/i.test(productName)) {
      showError('商品名に不正な文字が含まれています');
      return false;
    }

    return true;
  }

  // 在庫データを生成する関数（商品マスタと店舗マスタから）
  function generateInventoryData() {
    const inventoryData = [];

    productData.forEach(product => {
      storeData.forEach(store => {
        // ダミーの在庫データを生成
        const currentStock = Math.floor(Math.random() * 200);
        const safetyStock = Math.floor(Math.random() * 50) + 10;

        inventoryData.push({
          id: `${store.id}-${product.id}`,
          storeId: store.id,
          storeName: store.storeName || store.店舗名 || '',
          productId: product.id,
          productCode: product.productCode || product.商品コード || '',
          productName: product.productName || product.商品名 || '',
          currentStock: currentStock,
          safetyStock: safetyStock,
          unitPrice: product.unitPrice || product.単価 || 0,
          category: getProductCategory(product.productName || product.商品名 || ''),
          stockStatus: getStockStatus(currentStock, safetyStock)
        });
      });
    });

    return inventoryData;
  }

  // 商品名からカテゴリを推測する関数
  function getProductCategory(productName) {
    if (productName.includes('米') || productName.includes('パン') || productName.includes('肉') || productName.includes('魚')) {
      return '食品';
    } else if (productName.includes('洗剤') || productName.includes('石鹸') || productName.includes('タオル')) {
      return '日用品';
    } else if (productName.includes('シャツ') || productName.includes('パンツ') || productName.includes('靴')) {
      return '衣料品';
    } else if (productName.includes('テレビ') || productName.includes('冷蔵庫') || productName.includes('洗濯機')) {
      return '家電';
    }
    return '食品'; // デフォルト
  }

  // テーブル再描画関数
  function renderRows(rows) {
    if (!rows || rows.length === 0) {
      tbody.innerHTML = '';
      noResults.classList.remove('hidden');
      return;
    }

    noResults.classList.add('hidden');

    tbody.innerHTML = rows.map(row => `
      <tr data-id="${row.id}" style="border-bottom: 1px solid var(--border);">
        <td style="padding: 12px; color: var(--text); font-family: monospace;">${row.productCode || ''}</td>
        <td style="padding: 12px; color: var(--text);">${row.productName || ''}</td>
        <td style="padding: 12px; text-align: right; color: var(--text); font-weight: 500;">${row.currentStock || 0}</td>
        <td style="padding: 12px; text-align: right; color: var(--text);">${row.safetyStock || 0}</td>
        <td style="padding: 12px; text-align: center;">
          <span style="${getStatusStyle(row.stockStatus)}">${row.stockStatus || '適正'}</span>
        </td>
        <td style="padding: 12px; color: var(--text);">${row.category || ''}</td>
        <td style="padding: 12px; text-align: right; color: var(--text);">¥${(row.unitPrice || 0).toLocaleString()}</td>
        <td style="padding: 12px; text-align: center;">
          <button class="action-btn secondary" style="padding: 4px 8px; font-size: 12px;" onclick="window.showScreen('scr-1778591852463')">発注</button>
        </td>
      </tr>
    `).join('');
  }

  // 店舗選択肢を設定する関数
  function populateStoreOptions() {
    storeSelect.innerHTML = '<option value="">店舗を選択してください</option>';
    storeData.forEach(store => {
      const option = document.createElement('option');
      option.value = store.id;
      option.textContent = `${store.storeCode || store.店舗コード || ''} - ${store.storeName || store.店舗名 || ''}`;
      storeSelect.appendChild(option);
    });
  }

  // フィルタリング関数
  function filterInventoryData() {
    if (!validateInputs()) return;

    const storeId = storeSelect.value;
    const category = categoryFilter.value;
    const productName = productNameSearch.value.trim().toLowerCase();
    const productCode = productCodeSearch.value.trim().toLowerCase();
    const stockStatus = stockStatusFilter.value;

    let filteredData = allInventoryData.filter(item => item.storeId === storeId);

    if (category) {
      filteredData = filteredData.filter(item => item.category === category);
    }

    if (productName) {
      filteredData = filteredData.filter(item => 
        item.productName.toLowerCase().includes(productName)
      );
    }

    if (productCode) {
      filteredData = filteredData.filter(item => 
        item.productCode.toLowerCase().includes(productCode)
      );
    }

    if (stockStatus) {
      filteredData = filteredData.filter(item => item.stockStatus === stockStatus);
    }

    renderRows(filteredData);
  }

  // CSVエクスポート関数
  function exportToCSV() {
    const storeId = storeSelect.value;
    if (!storeId) {
      showError('店舗を選択してからエクスポートしてください');
      return;
    }

    const currentData = allInventoryData.filter(item => item.storeId === storeId);

    if (currentData.length === 0) {
      showError('エクスポートするデータがありません');
      return;
    }

    const headers = ['商品コード', '商品名', '現在在庫数', '安全在庫数', '在庫状況', 'カテゴリ', '単価'];
    const csvContent = '\uFEFF' + [
      headers.join(','),
      ...currentData.map(row => [
        `"${row.productCode || ''}"`,
        `"${row.productName || ''}"`,
        row.currentStock || 0,
        row.safetyStock || 0,
        `"${row.stockStatus || ''}"`,
        `"${row.category || ''}"`,
        row.unitPrice || 0
      ].join(','))
    ].join('\n');

    const blob = new Blob([csvContent], { type: 'text/csv;charset=utf-8;' });
    const link = document.createElement('a');
    const url = URL.createObjectURL(blob);
    link.setAttribute('href', url);
    link.setAttribute('download', `inventory_${new Date().toISOString().split('T')[0]}.csv`);
    link.style.visibility = 'hidden';
    document.body.appendChild(link);
    link.click();
    document.body.removeChild(link);
  }

  // 検索条件クリア関数
  function clearSearchConditions() {
    storeSelect.value = '';
    categoryFilter.value = '';
    productNameSearch.value = '';
    productCodeSearch.value = '';
    stockStatusFilter.value = '';
    tbody.innerHTML = '';
    noResults.classList.add('hidden');
    hideError();
  }

  // 初期データの読み込み
  async function loadInitialData() {
    try {
      // 店舗データの読み込み
      const stores = await window.aivicApi.list(1); // 店舗マスタ
      if (stores) {
        storeData = stores;
        populateStoreOptions();
      }

      // 商品データの読み込み
      const products = await window.aivicApi.list(2); // 商品マスタ
      if (products) {
        productData = products;
        allInventoryData = generateInventoryData();
      }
    } catch (error) {
      console.error('初期データの読み込みに失敗しました:', error);
      showError('データの読み込みに失敗しました');
    }
  }

  // イベントリスナーの設定
  container.querySelector('#btn-search').addEventListener('click', filterInventoryData);

  container.querySelector('#btn-clear').addEventListener('click', clearSearchConditions);

  container.querySelector('#btn-export').addEventListener('click', exportToCSV);

  // 店舗選択時の自動検索
  storeSelect.addEventListener('change', () => {
    if (storeSelect.value) {
      filterInventoryData();
    } else {
      tbody.innerHTML = '';
      noResults.classList.add('hidden');
    }
  });

  // Enterキーでの検索
  [productNameSearch, productCodeSearch].forEach(input => {
    input.addEventListener('keypress', (e) => {
      if (e.key === 'Enter') {
        filterInventoryData();
      }
    });
  });

  // 初期データ読み込み
  loadInitialData();
}

function(container, apiUrl, tables) {
  // テーブルインデックス定義
  const STORES_TABLE = 1; // 店舗マスタ
  const PRODUCTS_TABLE = 2; // 商品マスタ
  const DEMAND_FORECAST_TABLE = 8; // 需要予測結果
  const ORDER_TABLE = 9; // 発注データ

  let currentOrderData = [];
  let selectedItems = new Set();

  // 今日の日付を設定
  const today = new Date().toISOString().split('T')[0];
  container.querySelector('#input-order-date').value = today;
  container.querySelector('#input-order-date').min = today;

  // 店舗データ読み込み
  async function loadStores() {
    const stores = await window.aivicApi.list(STORES_TABLE);
    if (stores) {
      const storeSelect = container.querySelector('#select-store');
      storeSelect.innerHTML = '<option value="">店舗を選択してください</option>';
      stores.filter(s => s.有効フラグ).forEach(store => {
        storeSelect.innerHTML += `<option value="${store.店舗ID}">${store.店舗名}</option>`;
      });
    }
  }

  // 商品カテゴリ読み込み
  async function loadCategories() {
    const products = await window.aivicApi.list(PRODUCTS_TABLE);
    if (products) {
      const categories = [...new Set(products.map(p => p.商品カテゴリID))];
      const categorySelect = container.querySelector('#select-category');
      categorySelect.innerHTML = '<option value="">全てのカテゴリ</option>';
      categories.forEach(cat => {
        if (cat) {
          categorySelect.innerHTML += `<option value="${cat}">カテゴリ${cat}</option>`;
        }
      });
    }
  }

  // 発注データ表示
  function renderOrderData(data) {
    const tbody = container.querySelector('#order-tbody');

    if (!data || data.length === 0) {
      tbody.innerHTML = '<tr><td colspan="10" class="muted">データがありません</td></tr>';
      updateTotalSection();
      return;
    }

    tbody.innerHTML = data.map(item => `
      <tr data-product-id="${item.商品ID}">
        <td><input type="checkbox" class="item-checkbox" data-product-id="${item.商品ID}" /></td>
        <td>${item.商品コード || ''}</td>
        <td>${item.商品名 || ''}</td>
        <td class="text-right">${item.予測数量 || 0}</td>
        <td class="text-right">${item.推奨発注数量 || 0}</td>
        <td class="text-right">${item.現在在庫数量 || 0}</td>
        <td>
          <input type="number" class="input quantity-input" 
                 data-product-id="${item.商品ID}"
                 value="${item.推奨発注数量 || 0}" 
                 min="0" step="1" />
          <div class="error-message hidden" data-error-for="${item.商品ID}"></div>
        </td>
        <td class="text-right">${item.発注単価 || 0}円</td>
        <td class="text-right amount-display" data-amount-for="${item.商品ID}">
          ${((item.推奨発注数量 || 0) * (item.発注単価 || 0)).toLocaleString()}円
        </td>
        <td>
          <button class="action-btn secondary single-order-btn" data-product-id="${item.商品ID}">
            個別発注
          </button>
        </td>
      </tr>
    `).join('');

    updateTotalSection();
  }

  // 発注データ取得
  async function loadOrderData() {
    const storeId = container.querySelector('#select-store').value;
    const orderDate = container.querySelector('#input-order-date').value;
    const categoryId = container.querySelector('#select-category').value;

    if (!storeId) {
      renderOrderData([]);
      return;
    }

    try {
      // 需要予測結果を取得
      const forecasts = await window.aivicApi.list(DEMAND_FORECAST_TABLE);
      const products = await window.aivicApi.list(PRODUCTS_TABLE);

      if (!forecasts || !products) {
        renderOrderData([]);
        return;
      }

      // 店舗と日付でフィルタリング
      let filteredForecasts = forecasts.filter(f => 
        f.店舗ID === storeId && 
        f.予測対象日 && 
        f.予測対象日.split('T')[0] === orderDate
      );

      // カテゴリでフィルタリング
      if (categoryId) {
        const categoryProducts = products.filter(p => p.商品カテゴリID === categoryId);
        const categoryProductIds = categoryProducts.map(p => p.商品ID);
        filteredForecasts = filteredForecasts.filter(f => 
          categoryProductIds.includes(f.商品ID)
        );
      }

      // 商品情報と結合
      const orderData = filteredForecasts.map(forecast => {
        const product = products.find(p => p.商品ID === forecast.商品ID);
        return {
          商品ID: forecast.商品ID,
          商品コード: product?.商品コード || '',
          商品名: product?.商品名 || '',
          予測数量: forecast.予測数量 || 0,
          推奨発注数量: forecast.推奨発注数量 || 0,
          現在在庫数量: Math.floor(Math.random() * 100), // 実際は在庫システムから取得
          発注単価: product?.単価 || 0
        };
      });

      currentOrderData = orderData;
      renderOrderData(orderData);

    } catch (error) {
      console.error('発注データ読み込みエラー:', error);
      renderOrderData([]);
    }
  }

  // 合計セクション更新
  function updateTotalSection() {
    const checkboxes = container.querySelectorAll('.item-checkbox:checked');
    const totalSection = container.querySelector('#total-section');
    const bulkOrderBtn = container.querySelector('#btn-bulk-order');

    if (checkboxes.length > 0) {
      totalSection.classList.remove('hidden');
      bulkOrderBtn.disabled = false;

      let totalAmount = 0;
      checkboxes.forEach(cb => {
        const productId = cb.dataset.productId;
        const quantityInput = container.querySelector(`input[data-product-id="${productId}"]`);
        const item = currentOrderData.find(d => d.商品ID === productId);
        if (item && quantityInput) {
          const quantity = parseInt(quantityInput.value) || 0;
          totalAmount += quantity * (item.発注単価 || 0);
        }
      });

      container.querySelector('#selected-count').textContent = checkboxes.length;
      container.querySelector('#total-amount').textContent = totalAmount.toLocaleString();
    } else {
      totalSection.classList.add('hidden');
      bulkOrderBtn.disabled = true;
    }
  }

  // 発注金額計算
  function calculateAmount(productId, quantity) {
    const item = currentOrderData.find(d => d.商品ID === productId);
    if (!item) return 0;

    const amount = quantity * (item.発注単価 || 0);
    const amountDisplay = container.querySelector(`[data-amount-for="${productId}"]`);
    if (amountDisplay) {
      amountDisplay.textContent = `${amount.toLocaleString()}円`;
    }

    updateTotalSection();
    return amount;
  }

  // バリデーション
  function validateOrderQuantity(productId, quantity) {
    const errorDiv = container.querySelector(`[data-error-for="${productId}"]`);

    if (quantity === '' || quantity === null || quantity === undefined) {
      errorDiv.textContent = '発注数量を入力してください';
      errorDiv.classList.remove('hidden');
      return false;
    }

    if (isNaN(quantity) || !Number.isInteger(Number(quantity))) {
      errorDiv.textContent = '数値を入力してください';
      errorDiv.classList.remove('hidden');
      return false;
    }

    if (quantity < 0) {
      errorDiv.textContent = '発注数量は正の値を入力してください';
      errorDiv.classList.remove('hidden');
      return false;
    }

    if (quantity === 0) {
      errorDiv.textContent = '発注数量は1以上の値を入力してください';
      errorDiv.classList.remove('hidden');
      return false;
    }

    if (quantity > 99999) {
      errorDiv.textContent = '発注数量が上限を超えています';
      errorDiv.classList.remove('hidden');
      return false;
    }

    errorDiv.classList.add('hidden');
    return true;
  }

  // 発注実行
  async function executeOrder(items) {
    const storeId = container.querySelector('#select-store').value;
    const orderDate = container.querySelector('#input-order-date').value;

    if (!storeId) {
      alert('店舗を選択してください');
      return false;
    }

    if (!orderDate || orderDate < today) {
      alert('発注日付は本日以降の日付を選択してください');
      return false;
    }

    const orders = [];
    for (const item of items) {
      const quantity = parseInt(item.quantity);
      if (!validateOrderQuantity(item.productId, quantity)) {
        return false;
      }

      const productData = currentOrderData.find(d => d.商品ID === item.productId);
      if (!productData) continue;

      const orderData = {
        店舗ID: storeId,
        商品ID: item.productId,
        発注日: new Date(orderDate).toISOString(),
        納期予定日: new Date(Date.now() + 3 * 24 * 60 * 60 * 1000).toISOString(), // 3日後
        発注数量: quantity,
        予測数量: productData.予測数量,
        発注単価: productData.発注単価,
        発注金額: quantity * productData.発注単価,
        発注方法: 'AI推奨採用',
        発注ステータス: '発注済',
        仕入先ID: 'supplier-001', // 実際は商品マスタから取得
        発注理由: 'AI需要予測に基づく発注',
        自動発注フラグ: false,
        作成者ID: 'current-user-id',
        更新者ID: 'current-user-id'
      };

      orders.push(orderData);
    }

    try {
      for (const order of orders) {
        await window.aivicApi.save(ORDER_TABLE, order);
      }

      alert(`${orders.length}件の発注を実行しました`);

      // 選択状態をクリア
      selectedItems.clear();
      container.querySelectorAll('.item-checkbox').forEach(cb => cb.checked = false);
      container.querySelector('#check-all').checked = false;
      updateTotalSection();

      return true;
    } catch (error) {
      console.error('発注実行エラー:', error);
      alert('発注実行中にエラーが発生しました');
      return false;
    }
  }

  // 確認モーダル表示
  function showConfirmModal(items) {
    const modal = container.querySelector('#order-confirm-modal');
    const detailsDiv = container.querySelector('#confirm-details');

    let totalAmount = 0;
    const details = items.map(item => {
      const productData = currentOrderData.find(d => d.商品ID === item.productId);
      const amount = item.quantity * (productData?.発注単価 || 0);
      totalAmount += amount;

      return `
        <div style="display: flex; justify-content: space-between; padding: 0.5rem 0; border-bottom: 1px solid var(--border);">
          <span>${productData?.商品名 || ''}</span>
          <span>${item.quantity}個 × ${(productData?.発注単価 || 0).toLocaleString()}円 = ${amount.toLocaleString()}円</span>
        </div>
      `;
    }).join('');

    detailsDiv.innerHTML = `
      <div style="margin-bottom: 1rem;">
        <strong>発注内容確認</strong>
      </div>
      ${details}
      <div style="display: flex; justify-content: space-between; padding: 1rem 0; font-weight: bold; font-size: 1.1rem; border-top: 2px solid var(--border);">
        <span>合計</span>
        <span>${totalAmount.toLocaleString()}円</span>
      </div>
    `;

    modal.classList.remove('hidden');
  }

  // 初期化
  loadStores();
  loadCategories();

  // イベントリスナー

  // 店舗選択変更
  container.querySelector('#select-store').addEventListener('change', loadOrderData);

  // 発注日付変更
  container.querySelector('#input-order-date').addEventListener('change', loadOrderData);

  // カテゴリ選択変更
  container.querySelector('#select-category').addEventListener('change', loadOrderData);

  // 表示更新ボタン
  container.querySelector('#btn-refresh').addEventListener('click', loadOrderData);

  // 全選択チェックボックス
  container.querySelector('#check-all').addEventListener('change', (e) => {
    const checkboxes = container.querySelectorAll('.item-checkbox');
    checkboxes.forEach(cb => {
      cb.checked = e.target.checked;
      if (e.target.checked) {
        selectedItems.add(cb.dataset.productId);
      } else {
        selectedItems.delete(cb.dataset.productId);
      }
    });
    updateTotalSection();
  });

  // 数量入力変更
  container.addEventListener('input', (e) => {
    if (e.target.classList.contains('quantity-input')) {
      const productId = e.target.dataset.productId;
      const quantity = parseInt(e.target.value) || 0;
      calculateAmount(productId, quantity);
    }
  });

  // チェックボックス変更
  container.addEventListener('change', (e) => {
    if (e.target.classList.contains('item-checkbox')) {
      const productId = e.target.dataset.productId;
      if (e.target.checked) {
        selectedItems.add(productId);
      } else {
        selectedItems.delete(productId);
      }
      updateTotalSection();
    }
  });

  // まとめて発注実行
  container.querySelector('#btn-bulk-order').addEventListener('click', () => {
    const selectedCheckboxes = container.querySelectorAll('.item-checkbox:checked');
    if (selectedCheckboxes.length === 0) {
      alert('発注する商品を選択してください');
      return;
    }

    const items = Array.from(selectedCheckboxes).map(cb => {
      const productId = cb.dataset.productId;
      const quantityInput = container.querySelector(`input[data-product-id="${productId}"]`);
      return {
        productId: productId,
        quantity: parseInt(quantityInput.value) || 0
      };
    });

    showConfirmModal(items);
  });

  // 個別発注
  container.addEventListener('click', (e) => {
    if (e.target.classList.contains('single-order-btn')) {
      const productId = e.target.dataset.productId;
      const quantityInput = container.querySelector(`input[data-product-id="${productId}"]`);
      const quantity = parseInt(quantityInput.value) || 0;

      const items = [{
        productId: productId,
        quantity: quantity
      }];

      showConfirmModal(items);
    }
  });

  // モーダル確認ボタン
  container.querySelector('#btn-confirm-execute').addEventListener('click', async () => {
    const selectedCheckboxes = container.querySelectorAll('.item-checkbox:checked');
    const items = Array.from(selectedCheckboxes).map(cb => {
      const productId = cb.dataset.productId;
      const quantityInput = container.querySelector(`input[data-product-id="${productId}"]`);
      return {
        productId: productId,
        quantity: parseInt(quantityInput.value) || 0
      };
    });

    // 個別発注の場合は選択されたボタンから取得
    if (items.length === 0) {
      const activeBtn = container.querySelector('.single-order-btn:focus');
      if (activeBtn) {
        const productId = activeBtn.dataset.productId;
        const quantityInput = container.querySelector(`input[data-product-id="${productId}"]`);
        items.push({
          productId: productId,
          quantity: parseInt(quantityInput.value) || 0
        });
      }
    }

    const success = await executeOrder(items);
    if (success) {
      container.querySelector('#order-confirm-modal').classList.add('hidden');
    }
  });

  // モーダルキャンセルボタン
  container.querySelector('#btn-confirm-cancel').addEventListener('click', () => {
    container.querySelector('#order-confirm-modal').classList.add('hidden');
  });

  // モーダル背景クリックで閉じる
  container.querySelector('#order-confirm-modal').addEventListener('click', (e) => {
    if (e.target.id === 'order-confirm-modal') {
      container.querySelector('#order-confirm-modal').classList.add('hidden');
    }
  });
}

function(container, apiUrl, tables) {
  let currentData = [];
  let sortColumn = 'accuracy';
  let sortDirection = 'desc';
  let accuracyThreshold = 80; // 精度閾値

  // 店舗選択肢を初期化
  function initStoreOptions() {
    const storeSelect = container.querySelector('#store-filter');
    const stores = tables[1]?.records || [];
    stores.forEach(store => {
      const option = document.createElement('option');
      option.value = store.店舗ID;
      option.textContent = store.店舗名;
      storeSelect.appendChild(option);
    });
  }

  // チャート描画関数
  function drawAccuracyTrendChart(data) {
    const canvas = container.querySelector('#accuracy-trend-chart');
    const ctx = canvas.getContext('2d');

    // キャンバスをクリア
    ctx.clearRect(0, 0, canvas.width, canvas.height);

    if (!data || data.length === 0) {
      ctx.fillStyle = '#9fb0d1';
      ctx.font = '16px sans-serif';
      ctx.textAlign = 'center';
      ctx.fillText('データがありません', canvas.width / 2, canvas.height / 2);
      return;
    }

    const padding = 60;
    const chartWidth = canvas.width - padding * 2;
    const chartHeight = canvas.height - padding * 2;

    // 軸を描画
    ctx.strokeStyle = '#9fb0d1';
    ctx.lineWidth = 1;
    ctx.beginPath();
    ctx.moveTo(padding, padding);
    ctx.lineTo(padding, canvas.height - padding);
    ctx.lineTo(canvas.width - padding, canvas.height - padding);
    ctx.stroke();

    // データポイントを描画
    if (data.length > 1) {
      ctx.strokeStyle = '#4a9eff';
      ctx.lineWidth = 2;
      ctx.beginPath();

      data.forEach((point, index) => {
        const x = padding + (index / (data.length - 1)) * chartWidth;
        const y = canvas.height - padding - (point.accuracy / 100) * chartHeight;

        if (index === 0) {
          ctx.moveTo(x, y);
        } else {
          ctx.lineTo(x, y);
        }
      });
      ctx.stroke();
    }
  }

  function drawForecastVsActualChart(data) {
    const canvas = container.querySelector('#forecast-vs-actual-chart');
    const ctx = canvas.getContext('2d');

    ctx.clearRect(0, 0, canvas.width, canvas.height);

    if (!data || data.length === 0) {
      ctx.fillStyle = '#9fb0d1';
      ctx.font = '16px sans-serif';
      ctx.textAlign = 'center';
      ctx.fillText('データがありません', canvas.width / 2, canvas.height / 2);
      return;
    }

    const padding = 60;
    const chartWidth = canvas.width - padding * 2;
    const chartHeight = canvas.height - padding * 2;

    // 軸を描画
    ctx.strokeStyle = '#9fb0d1';
    ctx.lineWidth = 1;
    ctx.beginPath();
    ctx.moveTo(padding, padding);
    ctx.lineTo(padding, canvas.height - padding);
    ctx.lineTo(canvas.width - padding, canvas.height - padding);
    ctx.stroke();

    // 予測データ（青線）
    ctx.strokeStyle = '#4a9eff';
    ctx.lineWidth = 2;
    ctx.beginPath();
    data.forEach((point, index) => {
      const x = padding + (index / (data.length - 1)) * chartWidth;
      const y = canvas.height - padding - (point.forecast / Math.max(...data.map(d => Math.max(d.forecast, d.actual)))) * chartHeight;

      if (index === 0) {
        ctx.moveTo(x, y);
      } else {
        ctx.lineTo(x, y);
      }
    });
    ctx.stroke();

    // 実績データ（オレンジ線）
    ctx.strokeStyle = '#ff6a00';
    ctx.lineWidth = 2;
    ctx.beginPath();
    data.forEach((point, index) => {
      const x = padding + (index / (data.length - 1)) * chartWidth;
      const y = canvas.height - padding - (point.actual / Math.max(...data.map(d => Math.max(d.forecast, d.actual)))) * chartHeight;

      if (index === 0) {
        ctx.moveTo(x, y);
      } else {
        ctx.lineTo(x, y);
      }
    });
    ctx.stroke();

    // 凡例
    ctx.fillStyle = '#d0e4ff';
    ctx.font = '12px sans-serif';
    ctx.fillText('予測', canvas.width - 100, 30);
    ctx.fillText('実績', canvas.width - 100, 50);

    ctx.strokeStyle = '#4a9eff';
    ctx.lineWidth = 2;
    ctx.beginPath();
    ctx.moveTo(canvas.width - 120, 25);
    ctx.lineTo(canvas.width - 105, 25);
    ctx.stroke();

    ctx.strokeStyle = '#ff6a00';
    ctx.beginPath();
    ctx.moveTo(canvas.width - 120, 45);
    ctx.lineTo(canvas.width - 105, 45);
    ctx.stroke();
  }

  // ランキングテーブル再描画
  function renderRankingTable(data) {
    const tbody = container.querySelector('#ranking-tbody');
    if (!data || data.length === 0) {
      tbody.innerHTML = '<tr><td colspan="8" class="muted" style="text-align: center; padding: 2rem;">データがありません</td></tr>';
      return;
    }

    tbody.innerHTML = data.map((row, index) => `
      <tr data-id="${row.予測結果ID}">
        <td>${index + 1}</td>
        <td>${row.店舗名 || ''}</td>
        <td>${row.商品名 || ''}</td>
        <td style="color: ${row.accuracy >= accuracyThreshold ? '#4a9eff' : '#ff6a00'};">${row.accuracy?.toFixed(2) || '--'}%</td>
        <td>${row.mape?.toFixed(2) || '--'}</td>
        <td>${row.rmse?.toFixed(2) || '--'}</td>
        <td>${row.予測対象日 ? new Date(row.予測対象日).toLocaleDateString() : '--'}</td>
        <td>
          <button class="action-btn secondary detail-btn" data-id="${row.予測結果ID}">詳細分析</button>
        </td>
      </tr>
    `).join('');
  }

  // サマリー更新
  function updateSummary(data) {
    const overallAccuracy = data.length > 0 ? data.reduce((sum, item) => sum + (item.accuracy || 0), 0) / data.length : 0;
    const targetProducts = new Set(data.map(item => item.商品ID)).size;
    const alertCount = data.filter(item => (item.accuracy || 0) < accuracyThreshold).length;

    container.querySelector('#overall-accuracy').textContent = overallAccuracy.toFixed(1) + '%';
    container.querySelector('#target-products').textContent = targetProducts.toString();
    container.querySelector('#alert-count').textContent = alertCount.toString();

    const avgMape = data.length > 0 ? data.reduce((sum, item) => sum + (item.mape || 0), 0) / data.length : 0;
    const avgRmse = data.length > 0 ? data.reduce((sum, item) => sum + (item.rmse || 0), 0) / data.length : 0;

    container.querySelector('#mape-value').textContent = avgMape.toFixed(2);
    container.querySelector('#rmse-value').textContent = avgRmse.toFixed(2);
  }

  // アラート表示
  function updateAlerts(data) {
    const alertPanel = container.querySelector('#alert-panel');
    const template = container.querySelector('#alert-template');
    const noAlerts = container.querySelector('#no-alerts');

    // 既存のアラートをクリア
    const existingAlerts = alertPanel.querySelectorAll('.alert-item:not(#alert-template)');
    existingAlerts.forEach(alert => alert.remove());

    const alerts = data.filter(item => (item.accuracy || 0) < accuracyThreshold);

    if (alerts.length === 0) {
      noAlerts.style.display = 'block';
    } else {
      noAlerts.style.display = 'none';
      alerts.forEach(alert => {
        const alertElement = template.cloneNode(true);
        alertElement.id = '';
        alertElement.style.display = 'block';
        alertElement.querySelector('.alert-store').textContent = alert.店舗名 || '不明';
        alertElement.querySelector('.alert-product').textContent = alert.商品名 || '不明';
        alertElement.querySelector('.alert-accuracy').textContent = (alert.accuracy || 0).toFixed(2);
        alertElement.querySelector('.alert-timestamp').textContent = new Date().toLocaleString();
        alertPanel.appendChild(alertElement);
      });
    }
  }

  // データ読み込み
  async function loadData() {
    try {
      const forecastData = await window.aivicApi.list(4); // 需要予測結果
      if (!forecastData) {
        showError('データの取得に失敗しました。ネットワーク接続を確認してください。');
        return;
      }

      // 予測精度を計算（実績数量がある場合）
      const processedData = forecastData.map(item => {
        let accuracy = null;
        let mape = null;
        let rmse = null;

        if (item.実績数量 && item.予測数量) {
          const error = Math.abs(item.実績数量 - item.予測数量);
          mape = item.実績数量 > 0 ? (error / item.実績数量) * 100 : 0;
          accuracy = Math.max(0, 100 - mape);
          rmse = Math.sqrt(Math.pow(item.実績数量 - item.予測数量, 2));
        }

        return {
          ...item,
          accuracy,
          mape,
          rmse,
          店舗名: getStoreName(item.店舗ID),
          商品名: getProductName(item.商品ID)
        };
      }).filter(item => item.accuracy !== null);

      currentData = processedData;
      applyFilters();
    } catch (error) {
      showError('データの読み込み中にエラーが発生しました。');
    }
  }

  // 店舗名取得
  function getStoreName(storeId) {
    const store = tables[1]?.records?.find(s => s.店舗ID === storeId);
    return store?.店舗名 || '不明';
  }

  // 商品名取得
  function getProductName(productId) {
    const product = tables[2]?.records?.find(p => p.商品ID === productId);
    return product?.商品名 || '不明';
  }

  // フィルター適用
  function applyFilters() {
    const period = parseInt(container.querySelector('#period-filter').value);
    const storeId = container.querySelector('#store-filter').value;
    const category = container.querySelector('#category-filter').value;

    let filteredData = [...currentData];

    // 期間フィルター
    const cutoffDate = new Date();
    cutoffDate.setDate(cutoffDate.getDate() - period);
    filteredData = filteredData.filter(item => 
      !item.予測対象日 || new Date(item.予測対象日) >= cutoffDate
    );

    // 店舗フィルター
    if (storeId) {
      filteredData = filteredData.filter(item => item.店舗ID === storeId);
    }

    // カテゴリフィルター（簡易実装）
    if (category) {
      filteredData = filteredData.filter(item => 
        item.商品名?.includes(category) || false
      );
    }

    // ソート適用
    filteredData.sort((a, b) => {
      const aVal = a[sortColumn] || 0;
      const bVal = b[sortColumn] || 0;
      return sortDirection === 'asc' ? aVal - bVal : bVal - aVal;
    });

    renderRankingTable(filteredData);
    updateSummary(filteredData);
    updateAlerts(filteredData);

    // チャート用データ生成
    const chartData = filteredData.slice(0, 10).map((item, index) => ({
      accuracy: item.accuracy || 0,
      forecast: item.予測数量 || 0,
      actual: item.実績数量 || 0
    }));

    drawAccuracyTrendChart(chartData);
    drawForecastVsActualChart(chartData);
  }

  // エラー表示
  function showError(message) {
    const errorDiv = container.querySelector('#error-message');
    const errorText = container.querySelector('#error-text');
    errorText.textContent = message;
    errorDiv.classList.remove('hidden');
  }

  // エラー非表示
  function hideError() {
    container.querySelector('#error-message').classList.add('hidden');
  }

  // CSVエクスポート
  function exportCSV() {
    if (currentData.length === 0) {
      alert('エクスポートするデータがありません。');
      return;
    }

    const headers = ['順位', '店舗名', '商品名', '精度(%)', 'MAPE', 'RMSE', '期間'];
    const csvContent = '\uFEFF' + headers.join(',') + '\n' + 
      currentData.map((row, index) => [
        index + 1,
        `"${row.店舗名 || ''}"`,
        `"${row.商品名 || ''}"`,
        (row.accuracy || 0).toFixed(2),
        (row.mape || 0).toFixed(2),
        (row.rmse || 0).toFixed(2),
        row.予測対象日 ? new Date(row.予測対象日).toLocaleDateString() : ''
      ].join(',')).join('\n');

    const blob = new Blob([csvContent], { type: 'text/csv;charset=utf-8;' });
    const link = document.createElement('a');
    link.href = URL.createObjectURL(blob);
    link.download = `予測精度監視_${new Date().toISOString().split('T')[0]}.csv`;
    link.click();
  }

  // ソート処理
  function handleSort(column) {
    if (sortColumn === column) {
      sortDirection = sortDirection === 'asc' ? 'desc' : 'asc';
    } else {
      sortColumn = column;
      sortDirection = 'desc';
    }

    // ソートインジケーター更新
    container.querySelectorAll('.sort-indicator').forEach(indicator => {
      indicator.textContent = '';
    });

    const indicator = container.querySelector(`#sort-${column} .sort-indicator`);
    if (indicator) {
      indicator.textContent = sortDirection === 'asc' ? '↑' : '↓';
    }

    applyFilters();
  }

  // 初期化
  initStoreOptions();

  // 初期データ表示
  if (tables[4]?.records) {
    currentData = tables[4].records.map(item => ({
      ...item,
      accuracy: Math.random() * 40 + 60, // サンプル精度データ
      mape: Math.random() * 20 + 5,
      rmse: Math.random() * 10 + 2,
      店舗名: getStoreName(item.店舗ID),
      商品名: getProductName(item.商品ID)
    }));
    applyFilters();
  }

  // 実際のデータを読み込み
  loadData();

  // イベントリスナー
  container.querySelector('#btn-filter').addEventListener('click', applyFilters);

  container.querySelector('#btn-export').addEventListener('click', exportCSV);

  container.querySelector('#btn-report').addEventListener('click', () => {
    try {
      exportCSV();
    } catch (error) {
      showError('レポート出力に失敗しました。再度お試しください。');
    }
  });

  container.querySelector('#btn-retry').addEventListener('click', () => {
    hideError();
    loadData();
  });

  // ソートイベント
  ['rank', 'store', 'product', 'accuracy', 'mape', 'rmse', 'period'].forEach(column => {
    const header = container.querySelector(`#sort-${column}`);
    if (header) {
      header.addEventListener('click', () => handleSort(column));
    }
  });

  // 行レベル操作
  container.addEventListener('click', (e) => {
    const detailBtn = e.target.closest('.detail-btn');
    if (detailBtn) {
      const id = detailBtn.dataset.id;
      // 詳細分析画面への遷移（相関分析・比較分析画面を使用）
      window.showScreen('scr-1778591822586');
    }
  });
}

function(container, apiUrl, tables) {
  // テスト履歴データの再描画関数
  function renderTestHistory(rows) {
    const tbody = container.querySelector("#test-history-tbody");
    tbody.innerHTML = rows.map(r => `
      <tr data-id="${r.id}">
        <td>${r.testDate || ""}</td>
        <td>${r.modelName || ""}</td>
        <td>${r.testPeriod || ""}</td>
        <td>${r.storeCount || ""}</td>
        <td>${r.mape || ""}%</td>
        <td>${r.rmse || ""}</td>
        <td>${r.executionTime || ""}</td>
        <td>
          <button class="action-btn secondary view-detail-btn" data-id="${r.id}">詳細</button>
          <button class="action-btn secondary delete-btn" data-id="${r.id}">削除</button>
        </td>
      </tr>
    `).join("");
  }

  // 店舗チェックボックスの生成
  function renderStoreCheckboxes() {
    const storeCheckboxes = container.querySelector("#store-checkboxes");
    const storeData = tables.find(t => t.tableName === "店舗マスタ");
    if (storeData && storeData.records) {
      storeCheckboxes.innerHTML = storeData.records.map(store => `
        <label class="checkbox-label">
          <input type="checkbox" class="store-checkbox" value="${store.id}">
          ${store.storeName || store.storeCode || ""}
        </label>
      `).join("");
    }
  }

  // エラーメッセージ表示
  function showError(message) {
    const errorDiv = container.querySelector("#error-message");
    errorDiv.textContent = message;
    errorDiv.classList.remove("hidden");
    setTimeout(() => {
      errorDiv.classList.add("hidden");
    }, 5000);
  }

  // バリデーション
  function validateTestConfig() {
    const modelSelect = container.querySelector("#model-select").value;
    const startDate = container.querySelector("#test-start-date").value;
    const endDate = container.querySelector("#test-end-date").value;
    const categorySelect = container.querySelector("#category-select").value;
    const selectedDataset = container.querySelector('input[name="dataset"]:checked');
    const selectedStores = container.querySelectorAll('.store-checkbox:checked');

    if (!modelSelect) {
      showError("モデルが選択されていません。モデルを選択してください。");
      return false;
    }

    if (!startDate || !endDate) {
      showError("テスト期間を設定してください。");
      return false;
    }

    if (new Date(startDate) > new Date(endDate)) {
      showError("開始日は終了日より前の日付を入力してください。");
      return false;
    }

    if (selectedStores.length === 0) {
      showError("店舗が選択されていません。対象店舗を選択してください。");
      return false;
    }

    if (!categorySelect) {
      showError("商品カテゴリが未選択です。商品カテゴリを選択してください。");
      return false;
    }

    if (!selectedDataset) {
      showError("テストデータセットが選択されていません。");
      return false;
    }

    return true;
  }

  // 予測精度指標の更新
  function updateMetrics(metrics) {
    container.querySelector("#mape-value").textContent = metrics.mape || "-";
    container.querySelector("#rmse-value").textContent = metrics.rmse || "-";
    container.querySelector("#mae-value").textContent = metrics.mae || "-";
    container.querySelector("#r2-value").textContent = metrics.r2 || "-";
    container.querySelector("#execution-time").textContent = metrics.executionTime || "-";
  }

  // グラフ描画
  function drawComparisonChart(actualData, predictedData) {
    const canvas = container.querySelector("#comparison-chart");
    const ctx = canvas.getContext("2d");

    // キャンバスクリア
    ctx.clearRect(0, 0, canvas.width, canvas.height);

    if (!actualData || !predictedData || actualData.length === 0) {
      ctx.fillStyle = "#9fb0d1";
      ctx.font = "16px sans-serif";
      ctx.textAlign = "center";
      ctx.fillText("テストを実行すると比較グラフが表示されます", canvas.width / 2, canvas.height / 2);
      return;
    }

    const padding = 60;
    const chartWidth = canvas.width - padding * 2;
    const chartHeight = canvas.height - padding * 2;

    // 軸描画
    ctx.strokeStyle = "#9fb0d1";
    ctx.lineWidth = 1;
    ctx.beginPath();
    ctx.moveTo(padding, padding);
    ctx.lineTo(padding, canvas.height - padding);
    ctx.lineTo(canvas.width - padding, canvas.height - padding);
    ctx.stroke();

    // データ描画
    if (actualData.length > 1) {
      const maxValue = Math.max(...actualData, ...predictedData);
      const stepX = chartWidth / (actualData.length - 1);

      // 実績値線
      ctx.strokeStyle = "#007bff";
      ctx.lineWidth = 2;
      ctx.beginPath();
      actualData.forEach((value, index) => {
        const x = padding + index * stepX;
        const y = canvas.height - padding - (value / maxValue) * chartHeight;
        if (index === 0) ctx.moveTo(x, y);
        else ctx.lineTo(x, y);
      });
      ctx.stroke();

      // 予測値線
      ctx.strokeStyle = "#ff6a00";
      ctx.lineWidth = 2;
      ctx.beginPath();
      predictedData.forEach((value, index) => {
        const x = padding + index * stepX;
        const y = canvas.height - padding - (value / maxValue) * chartHeight;
        if (index === 0) ctx.moveTo(x, y);
        else ctx.lineTo(x, y);
      });
      ctx.stroke();

      // 凡例
      ctx.fillStyle = "#007bff";
      ctx.fillRect(padding, 20, 20, 10);
      ctx.fillStyle = "#d0e4ff";
      ctx.font = "12px sans-serif";
      ctx.fillText("実績値", padding + 30, 30);

      ctx.fillStyle = "#ff6a00";
      ctx.fillRect(padding + 100, 20, 20, 10);
      ctx.fillStyle = "#d0e4ff";
      ctx.fillText("予測値", padding + 130, 30);
    }
  }

  // モデルパラメータ表示
  function updateModelParameters(modelName) {
    const parameterDetails = container.querySelector("#parameter-details");
    const parameters = {
      "lstm-v1.2": {
        "アーキテクチャ": "LSTM",
        "隠れ層数": "3層",
        "ニューロン数": "128",
        "学習率": "0.001",
        "バッチサイズ": "32",
        "エポック数": "100"
      },
      "arima-v2.1": {
        "モデル": "ARIMA",
        "p値": "2",
        "d値": "1", 
        "q値": "2",
        "季節性": "有り",
        "季節周期": "7日"
      },
      "xgboost-v1.5": {
        "アルゴリズム": "XGBoost",
        "木の深さ": "6",
        "学習率": "0.1",
        "推定器数": "100",
        "正則化": "L2"
      }
    };

    const params = parameters[modelName];
    if (params) {
      parameterDetails.innerHTML = Object.entries(params).map(([key, value]) => 
        `<div style="margin-bottom: 8px;"><strong>${key}:</strong> ${value}</div>`
      ).join("");
    } else {
      parameterDetails.innerHTML = '<p class="muted">モデルを選択してテストを実行すると、パラメータ詳細が表示されます</p>';
    }
  }

  // 初期データ読み込み
  renderTestHistory(tables[0]?.records || []);
  renderStoreCheckboxes();
  drawComparisonChart([], []);

  // 全店舗選択チェックボックス
  container.querySelector("#select-all-stores").addEventListener("change", (e) => {
    const checkboxes = container.querySelectorAll(".store-checkbox");
    checkboxes.forEach(cb => cb.checked = e.target.checked);
  });

  // テスト実行ボタン
  container.querySelector("#btn-test-execute").addEventListener("click", async () => {
    if (!validateTestConfig()) return;

    const modelName = container.querySelector("#model-select").value;
    const startDate = container.querySelector("#test-start-date").value;
    const endDate = container.querySelector("#test-end-date").value;
    const category = container.querySelector("#category-select").value;
    const dataset = container.querySelector('input[name="dataset"]:checked').value;
    const selectedStores = Array.from(container.querySelectorAll('.store-checkbox:checked')).map(cb => cb.value);

    // テスト実行のシミュレーション
    const testResult = {
      testDate: new Date().toLocaleString(),
      modelName: modelName,
      testPeriod: `${startDate} ～ ${endDate}`,
      storeCount: selectedStores.length,
      mape: (Math.random() * 10 + 5).toFixed(2),
      rmse: (Math.random() * 50 + 20).toFixed(1),
      mae: (Math.random() * 30 + 10).toFixed(1),
      r2: (Math.random() * 0.3 + 0.7).toFixed(3),
      executionTime: `${(Math.random() * 300 + 60).toFixed(0)}秒`
    };

    // 結果表示
    updateMetrics(testResult);
    updateModelParameters(modelName);

    // サンプルデータでグラフ描画
    const actualData = Array.from({length: 30}, () => Math.random() * 100 + 50);
    const predictedData = actualData.map(v => v + (Math.random() - 0.5) * 20);
    drawComparisonChart(actualData, predictedData);

    // テスト履歴に保存
    const saved = await window.aivicApi.save(0, testResult);
    if (saved) {
      const rows = await window.aivicApi.list(0);
      if (rows) renderTestHistory(rows);
    }
  });

  // エクスポートボタン
  container.querySelector("#btn-test-export").addEventListener("click", async () => {
    const rows = await window.aivicApi.list(0);
    if (!rows || rows.length === 0) {
      showError("エクスポートするテスト結果がありません。");
      return;
    }

    const headers = ["テスト日時", "モデル名", "テスト期間", "対象店舗数", "MAPE", "RMSE", "実行時間"];
    const csvContent = "\uFEFF" + [
      headers.join(","),
      ...rows.map(r => [
        r.testDate || "",
        r.modelName || "",
        r.testPeriod || "",
        r.storeCount || "",
        r.mape || "",
        r.rmse || "",
        r.executionTime || ""
      ].join(","))
    ].join("\n");

    const blob = new Blob([csvContent], { type: "text/csv;charset=utf-8;" });
    const link = document.createElement("a");
    link.href = URL.createObjectURL(blob);
    link.download = "model_test_results.csv";
    link.click();
  });

  // イベントデリゲーション（削除・詳細表示）
  container.addEventListener("click", async (e) => {
    const deleteBtn = e.target.closest(".delete-btn");
    if (deleteBtn) {
      if (!confirm("このテスト結果を削除しますか？")) return;
      await window.aivicApi.delete(0, deleteBtn.dataset.id);
      const rows = await window.aivicApi.list(0);
      if (rows) renderTestHistory(rows);
      return;
    }

    const viewDetailBtn = e.target.closest(".view-detail-btn");
    if (viewDetailBtn) {
      // 詳細画面への遷移（実装例）
      window.showScreen("scr-1778591974844"); // 予測精度監視画面
      return;
    }
  });
}

function(container, apiUrl, tables) {
  let currentModels = [];
  let currentStores = [];
  let validationPassed = false;
  let deploymentInProgress = false;

  // モデル一覧を取得してドロップダウンに設定
  async function loadModels() {
    try {
      // 需要予測結果テーブルからモデルバージョンを取得
      const predictions = await window.aivicApi.list(9) || [];
      const modelVersions = [...new Set(predictions.map(p => p.予測モデルバージョン).filter(v => v))];

      const selectModel = container.querySelector('#select-model');
      selectModel.innerHTML = '<option value="">-- モデルを選択してください --</option>';

      modelVersions.forEach(version => {
        const option = document.createElement('option');
        option.value = version;
        option.textContent = `モデル ${version}`;
        selectModel.appendChild(option);
      });

      currentModels = modelVersions.map(version => ({
        version,
        name: `AI需要予測モデル ${version}`,
        created: new Date().toISOString(),
        accuracy: Math.floor(Math.random() * 20) + 80 // 80-99%
      }));
    } catch (error) {
      console.error('モデル読み込みエラー:', error);
    }
  }

  // 店舗一覧を取得してチェックボックスに設定
  async function loadStores() {
    try {
      const stores = await window.aivicApi.list(1) || [];
      currentStores = stores;

      const storeList = container.querySelector('#store-list');
      storeList.innerHTML = stores.map(store => `
        <label style="display: flex; align-items: center; gap: 8px; margin: 4px 0;">
          <input type="checkbox" class="store-checkbox" value="${store.店舗ID}">
          <span>${store.店舗名} (${store.店舗コード})</span>
        </label>
      `).join('');
    } catch (error) {
      console.error('店舗読み込みエラー:', error);
    }
  }

  // モデル選択時の詳細表示
  container.querySelector('#select-model').addEventListener('change', function() {
    const selectedVersion = this.value;
    const modelDetails = container.querySelector('#model-details');

    if (selectedVersion) {
      const model = currentModels.find(m => m.version === selectedVersion);
      if (model) {
        container.querySelector('#model-name').textContent = model.name;
        container.querySelector('#model-version').textContent = model.version;
        container.querySelector('#model-created').textContent = new Date(model.created).toLocaleString();
        container.querySelector('#model-accuracy').textContent = `${model.accuracy}%`;
        modelDetails.style.display = 'block';
      }
    } else {
      modelDetails.style.display = 'none';
    }

    // 検証結果をリセット
    validationPassed = false;
    container.querySelector('#validation-results').style.display = 'none';
    container.querySelector('#impact-analysis').style.display = 'none';
    container.querySelector('#btn-execute').disabled = true;
  });

  // 全店舗選択チェックボックス
  container.querySelector('#select-all-stores').addEventListener('change', function() {
    const checkboxes = container.querySelectorAll('.store-checkbox');
    checkboxes.forEach(cb => cb.checked = this.checked);
  });

  // 適用前検証実行
  container.querySelector('#btn-validate').addEventListener('click', async function() {
    const selectedModel = container.querySelector('#select-model').value;
    const selectedStores = Array.from(container.querySelectorAll('.store-checkbox:checked')).map(cb => cb.value);
    const startDateTime = container.querySelector('#input-start-datetime').value;

    // バリデーション
    if (!selectedModel) {
      alert('適用対象モデルを選択してください。');
      return;
    }
    if (selectedStores.length === 0) {
      alert('適用対象店舗を選択してください。');
      return;
    }
    if (!startDateTime) {
      alert('適用開始日時を入力してください。');
      return;
    }
    if (new Date(startDateTime) < new Date()) {
      alert('適用開始日時には現在日時以降を指定してください。');
      return;
    }

    // 検証実行
    this.disabled = true;
    this.textContent = '検証中...';

    try {
      // 模擬検証処理
      await new Promise(resolve => setTimeout(resolve, 2000));

      // 検証結果表示
      const validationResults = container.querySelector('#validation-results');
      const validationStatusText = container.querySelector('#validation-status-text');
      const validationDetails = container.querySelector('#validation-details');

      // ランダムで検証結果を決定（テスト用）
      const isValidationSuccess = Math.random() > 0.2; // 80%の確率で成功

      if (isValidationSuccess) {
        validationStatusText.textContent = '検証成功';
        validationStatusText.style.color = '#28a745';
        validationDetails.innerHTML = `
          <div style="color: var(--text);">
            ✓ データ品質チェック: 正常<br>
            ✓ 精度閾値チェック: 正常<br>
            ✓ 依存関係チェック: 正常<br>
            ✓ リソース使用量チェック: 正常
          </div>
        `;
        validationPassed = true;
        container.querySelector('#btn-execute').disabled = false;

        // 影響範囲表示
        container.querySelector('#impact-stores').textContent = selectedStores.length;
        container.querySelector('#impact-products').textContent = Math.floor(Math.random() * 500) + 100;
        container.querySelector('#impact-duration').textContent = `約${Math.floor(selectedStores.length * 2)}分`;
        container.querySelector('#impact-level').textContent = selectedStores.length > 10 ? '高' : selectedStores.length > 5 ? '中' : '低';
        container.querySelector('#impact-analysis').style.display = 'block';
      } else {
        validationStatusText.textContent = '検証失敗';
        validationStatusText.style.color = '#dc3545';
        validationDetails.innerHTML = `
          <div style="color: var(--text);">
            ✓ データ品質チェック: 正常<br>
            ✗ 精度閾値チェック: 閾値を下回っています<br>
            ✓ 依存関係チェック: 正常<br>
            ✓ リソース使用量チェック: 正常
          </div>
        `;
        validationPassed = false;
        container.querySelector('#btn-execute').disabled = true;
      }

      validationResults.style.display = 'block';
    } catch (error) {
      alert('検証処理中にエラーが発生しました。');
      console.error('検証エラー:', error);
    } finally {
      this.disabled = false;
      this.textContent = '適用前検証実行';
    }
  });

  // 適用実行
  container.querySelector('#btn-execute').addEventListener('click', async function() {
    if (!validationPassed) {
      alert('適用前検証が完了していません。');
      return;
    }

    if (!confirm('モデルの本番適用を実行しますか？')) {
      return;
    }

    deploymentInProgress = true;
    this.disabled = true;
    container.querySelector('#btn-validate').disabled = true;

    const progressSection = container.querySelector('#progress-section');
    const progressFill = container.querySelector('#progress-fill');
    const progressText = container.querySelector('#progress-text');
    const progressPercent = container.querySelector('#progress-percent');
    const logSection = container.querySelector('#log-section');
    const logContent = container.querySelector('#log-content');

    progressSection.style.display = 'block';
    logSection.style.display = 'block';

    const steps = [
      { text: 'モデル検証中...', duration: 2000 },
      { text: 'バックアップ作成中...', duration: 3000 },
      { text: 'モデルデプロイ中...', duration: 4000 },
      { text: '本番切替中...', duration: 2000 },
      { text: '動作確認中...', duration: 1000 }
    ];

    let currentProgress = 0;
    const totalSteps = steps.length;

    function addLog(message) {
      const timestamp = new Date().toLocaleTimeString();
      logContent.innerHTML += `[${timestamp}] ${message}\n`;
      logContent.scrollTop = logContent.scrollHeight;
    }

    addLog('モデル本番適用処理を開始しました。');

    try {
      for (let i = 0; i < steps.length; i++) {
        const step = steps[i];
        progressText.textContent = step.text;
        addLog(step.text);

        // 進捗バー更新
        const targetProgress = ((i + 1) / totalSteps) * 100;
        const startProgress = currentProgress;
        const progressDiff = targetProgress - startProgress;

        const startTime = Date.now();
        const updateProgress = () => {
          const elapsed = Date.now() - startTime;
          const progress = Math.min(elapsed / step.duration, 1);
          const currentValue = startProgress + (progressDiff * progress);

          progressFill.style.width = `${currentValue}%`;
          progressPercent.textContent = `${Math.floor(currentValue)}%`;

          if (progress < 1) {
            requestAnimationFrame(updateProgress);
          } else {
            currentProgress = targetProgress;
          }
        };
        updateProgress();

        await new Promise(resolve => setTimeout(resolve, step.duration));
        addLog(`${step.text} 完了`);
      }

      progressText.textContent = '適用完了';
      addLog('モデル本番適用処理が正常に完了しました。');

      // ロールバックボタンを表示
      container.querySelector('#rollback-section').style.display = 'block';

      alert('モデルの本番適用が正常に完了しました。');
    } catch (error) {
      progressText.textContent = 'エラー発生';
      addLog(`エラー: ${error.message}`);
      alert('適用処理中にシステムエラーが発生しました。管理者にお問い合わせください。');
    } finally {
      deploymentInProgress = false;
      this.disabled = false;
      container.querySelector('#btn-validate').disabled = false;
    }
  });

  // ロールバック実行
  container.querySelector('#btn-rollback').addEventListener('click', async function() {
    if (!confirm('前バージョンのモデルにロールバックしますか？\nこの操作は取り消せません。')) {
      return;
    }

    this.disabled = true;
    this.textContent = 'ロールバック中...';

    const logContent = container.querySelector('#log-content');

    function addLog(message) {
      const timestamp = new Date().toLocaleTimeString();
      logContent.innerHTML += `[${timestamp}] ${message}\n`;
      logContent.scrollTop = logContent.scrollHeight;
    }

    try {
      addLog('ロールバック処理を開始しました。');
      await new Promise(resolve => setTimeout(resolve, 3000));
      addLog('前バージョンのモデルに切り替え完了。');
      addLog('ロールバック処理が正常に完了しました。');

      alert('ロールバックが正常に完了しました。');

      // UI状態をリセット
      container.querySelector('#rollback-section').style.display = 'none';
      container.querySelector('#progress-section').style.display = 'none';
      validationPassed = false;
      container.querySelector('#btn-execute').disabled = true;
    } catch (error) {
      addLog(`ロールバックエラー: ${error.message}`);
      alert('ロールバック処理中にエラーが発生しました。');
    } finally {
      this.disabled = false;
      this.textContent = 'ロールバック実行';
    }
  });

  // 現在日時を適用開始日時のデフォルトに設定
  const now = new Date();
  now.setMinutes(now.getMinutes() - now.getTimezoneOffset());
  container.querySelector('#input-start-datetime').value = now.toISOString().slice(0, 16);

  // 初期データ読み込み
  loadModels();
  loadStores();
}
